);

CREATE TABLE IF NOT EXISTS tags (
  id VARCHAR PRIMARY KEY,
  label_de VARCHAR NOT NULL,
  label_en VARCHAR NOT NULL
);

CREATE TABLE IF NOT EXISTS exercise_tags (
  exercise_id UUID NOT NULL REFERENCES exercises(id),
