-- Source migration: 004_exercise_details.sql
-- Searchable exercise instructions are localized; logistics/classification stay
-- structured on the exercise record. Ordered coaching text lives in child rows.
CREATE TABLE IF NOT EXISTS exercise_details (
  exercise_id UUID NOT NULL REFERENCES exercises(id),
  locale VARCHAR NOT NULL CHECK (locale IN ('de','en')),
  purpose VARCHAR NOT NULL,
  setup VARCHAR NOT NULL,
  start_position VARCHAR NOT NULL,
  finish_reset VARCHAR NOT NULL,
  breathing_cue VARCHAR NOT NULL,
  tempo_cue VARCHAR NOT NULL,
  safety_notes VARCHAR NOT NULL,
  quality_criteria VARCHAR NOT NULL,
  beginner_prescription VARCHAR NOT NULL,
  standard_prescription VARCHAR NOT NULL,
  advanced_prescription VARCHAR NOT NULL,
  work_rest_guidance VARCHAR NOT NULL,
  level_1 VARCHAR NOT NULL,
  level_2 VARCHAR NOT NULL,
  level_3 VARCHAR NOT NULL,
  child_youth_variant VARCHAR NOT NULL,
  prerequisites VARCHAR NOT NULL,
  fallback_exercise VARCHAR NOT NULL,
  difficulty VARCHAR NOT NULL CHECK (difficulty IN ('beginner','intermediate','advanced')),
  supervision VARCHAR NOT NULL CHECK (supervision IN ('normal','increased','direct')),
  space_requirement VARCHAR NOT NULL,
  setup_seconds INTEGER NOT NULL,
  transition_seconds INTEGER NOT NULL,
  station_capacity INTEGER NOT NULL,
  PRIMARY KEY (exercise_id, locale)
);

CREATE TABLE IF NOT EXISTS exercise_execution_steps (
  exercise_id UUID NOT NULL REFERENCES exercises(id),
  locale VARCHAR NOT NULL CHECK (locale IN ('de','en')),
  step_order SMALLINT NOT NULL,
  instruction VARCHAR NOT NULL,
  PRIMARY KEY (exercise_id, locale, step_order)
);
CREATE TABLE IF NOT EXISTS exercise_coaching_cues (
  exercise_id UUID NOT NULL REFERENCES exercises(id),
  locale VARCHAR NOT NULL CHECK (locale IN ('de','en')),
  cue_order SMALLINT NOT NULL,
  cue VARCHAR NOT NULL,
  PRIMARY KEY (exercise_id, locale, cue_order)
);
CREATE TABLE IF NOT EXISTS exercise_common_mistakes (
  exercise_id UUID NOT NULL REFERENCES exercises(id),
  locale VARCHAR NOT NULL CHECK (locale IN ('de','en')),
  mistake_order SMALLINT NOT NULL,
  mistake VARCHAR NOT NULL,
  correction VARCHAR NOT NULL,
  PRIMARY KEY (exercise_id, locale, mistake_order)
);
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS exercise_type VARCHAR DEFAULT 'drill';
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS difficulty VARCHAR DEFAULT 'beginner';
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS impact_level VARCHAR DEFAULT 'low';
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS coordination_complexity VARCHAR DEFAULT 'simple';
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS progression_required BOOLEAN DEFAULT false;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS space_requirement VARCHAR DEFAULT 'medium';
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS supports_reps BOOLEAN DEFAULT true;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS supports_seconds BOOLEAN DEFAULT true;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS supports_minutes BOOLEAN DEFAULT false;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS supports_metres BOOLEAN DEFAULT false;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS supports_rounds BOOLEAN DEFAULT true;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS supports_attempts BOOLEAN DEFAULT false;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS setup_seconds INTEGER DEFAULT 60;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS transition_seconds INTEGER DEFAULT 30;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS station_capacity INTEGER DEFAULT 1;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS suitable_for_kids BOOLEAN DEFAULT true;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS suitable_for_youth BOOLEAN DEFAULT true;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS suitable_for_adults BOOLEAN DEFAULT true;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS supervision VARCHAR DEFAULT 'normal';
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS indoor_suitable BOOLEAN DEFAULT true;
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS outdoor_suitable BOOLEAN DEFAULT true;

UPDATE exercises SET
  exercise_type = CASE category WHEN 'running' THEN 'endurance' WHEN 'mobility' THEN 'mobility' WHEN 'cooldown' THEN 'recovery' WHEN 'ocr-skill' THEN 'obstacle' WHEN 'balance-agility' THEN 'skill' WHEN 'throw' THEN 'skill' ELSE 'strength' END,
  difficulty = CASE WHEN risk_level='high' THEN 'advanced' WHEN risk_level='medium' THEN 'intermediate' ELSE 'beginner' END,
  impact_level = CASE WHEN seed_key LIKE '%jump%' OR seed_key LIKE '%bounding%' THEN 'high' WHEN category='running' OR category='balance-agility' THEN 'moderate' ELSE 'low' END,
  coordination_complexity = CASE WHEN risk_level='high' OR category IN ('ocr-skill','balance-agility','throw') THEN 'complex' WHEN category IN ('running','grip-rig') THEN 'moderate' ELSE 'simple' END,
  progression_required = category IN ('ocr-skill','grip-rig','throw') AND risk_level IN ('medium','high'),
  supervision = CASE WHEN risk_level='high' OR category IN ('ocr-skill','grip-rig') THEN 'direct' WHEN risk_level='medium' THEN 'increased' ELSE 'normal' END,
  space_requirement = CASE WHEN category='running' THEN 'running-route' WHEN category IN ('ocr-skill','grip-rig') THEN 'rig-area' WHEN category IN ('throw','carry-lift') THEN 'large' ELSE 'small' END,
  supports_metres = category IN ('running','carry-lift'),
  supports_minutes = category IN ('running','cooldown'),
  supports_attempts = category IN ('ocr-skill','throw','grip-rig'),
  setup_seconds = CASE WHEN category IN ('ocr-skill','grip-rig','throw') THEN 180 ELSE 60 END,
  transition_seconds = CASE WHEN category IN ('ocr-skill','grip-rig','throw') THEN 45 ELSE 20 END,
  station_capacity = CASE WHEN category IN ('ocr-skill','grip-rig','throw') THEN 1 WHEN category='running' THEN 12 ELSE 4 END,
  suitable_for_kids = min_age IS NULL OR min_age <= 12,
  suitable_for_youth = min_age IS NULL OR min_age <= 16
WHERE seed_key IS NOT NULL;

INSERT INTO exercise_details (exercise_id,locale,purpose,setup,start_position,finish_reset,breathing_cue,tempo_cue,safety_notes,quality_criteria,beginner_prescription,standard_prescription,advanced_prescription,work_rest_guidance,level_1,level_2,level_3,child_youth_variant,prerequisites,fallback_exercise,difficulty,supervision,space_requirement,setup_seconds,transition_seconds,station_capacity)
SELECT e.id, l.locale,
  CASE e.category WHEN 'running' THEN CASE l.locale WHEN 'de' THEN 'Verbessert die Lauf-Ausdauer oder Lauftechnik in einer kontrollierbaren Belastung.' ELSE 'Builds running endurance or technique at a controllable effort.' END
    WHEN 'grip-rig' THEN CASE l.locale WHEN 'de' THEN 'Entwickelt Griffkraft und sicheres Bewegen am Rig in kleinen, kontrollierten Schritten.' ELSE 'Develops grip strength and controlled movement on the rig.' END
    WHEN 'ocr-skill' THEN CASE l.locale WHEN 'de' THEN 'Übt eine Hindernisbewegung mit klarer Progression und sicherem Ausstieg.' ELSE 'Practises an obstacle movement with a clear progression and safe exit.' END
    WHEN 'carry-lift' THEN CASE l.locale WHEN 'de' THEN 'Trainiert das sichere Aufnehmen und Transportieren einer Last mit stabiler Körperhaltung.' ELSE 'Trains safe lifting and carrying with a stable posture.' END
    WHEN 'cooldown' THEN CASE l.locale WHEN 'de' THEN 'Senkt das Tempo und unterstützt ruhige Atmung und Beweglichkeit nach der Belastung.' ELSE 'Reduces effort and supports calm breathing and mobility after training.' END
    WHEN 'mobility' THEN CASE l.locale WHEN 'de' THEN 'Bereitet Gelenke kontrolliert auf die Bewegungen der Einheit vor.' ELSE 'Prepares joints in a controlled way for the session movements.' END
    ELSE CASE l.locale WHEN 'de' THEN 'Übt die Bewegung mit stabiler Technik und einer an die Gruppe angepassten Belastung.' ELSE 'Practises the movement with stable technique and workload matched to the group.' END END,
  CASE WHEN e.category IN ('ocr-skill','grip-rig','throw') THEN CASE l.locale WHEN 'de' THEN 'Prüfe Gerät und freie Sicherheitszone; richte eine klare Warte- und Bewegungsrichtung ein.' ELSE 'Check equipment and the clear safety zone; set a waiting area and one-way movement.' END
    WHEN e.category='running' THEN CASE l.locale WHEN 'de' THEN 'Markiere eine freie Strecke mit Wendepunkten; prüfe Boden, Verkehr und Gruppengröße.' ELSE 'Mark a clear route and turn points; check surface, traffic and group size.' END
    ELSE CASE l.locale WHEN 'de' THEN 'Schaffe rutschfesten Platz und lege benötigtes Material griffbereit an den Rand.' ELSE 'Clear a non-slip space and place any needed equipment within reach.' END END,
  CASE WHEN e.category='running' THEN CASE l.locale WHEN 'de' THEN 'Aufrecht stehen, Blick nach vorn, Schultern locker; starte erst auf Signal.' ELSE 'Stand tall, look ahead and relax the shoulders; start on the signal.' END
    WHEN e.category IN ('ocr-skill','grip-rig') THEN CASE l.locale WHEN 'de' THEN 'Warte hinter der Markierung und beginne nur am geprüften, freigegebenen Gerät.' ELSE 'Wait behind the marker and start only on inspected, approved equipment.' END
    ELSE CASE l.locale WHEN 'de' THEN 'Nimm eine stabile, schmerzfreie Ausgangsposition ein und richte den Blick auf den Bewegungsweg.' ELSE 'Take a stable, pain-free starting position and look along the movement path.' END END,
  CASE l.locale WHEN 'de' THEN 'Kehre kontrolliert zum Start zurück, sichere Material und gib den Platz für die nächste Person frei.' ELSE 'Return under control, secure equipment and clear the space for the next person.' END,
  CASE l.locale WHEN 'de' THEN 'Atme gleichmäßig; halte nicht die Luft an. Bei Anstrengung ruhig ausatmen.' ELSE 'Breathe steadily; do not hold your breath. Exhale calmly during effort.' END,
  CASE WHEN e.category='running' THEN CASE l.locale WHEN 'de' THEN 'Locker und gleichmäßig beginnen; Tempo nur steigern, solange die Technik sauber bleibt.' ELSE 'Start easy and even; increase pace only while technique stays smooth.' END ELSE CASE l.locale WHEN 'de' THEN 'Kontrolliert bewegen, kurz stabilisieren und ohne Schwung in die nächste Wiederholung gehen.' ELSE 'Move with control, stabilise briefly and avoid swinging into the next repetition.' END END,
  CASE WHEN e.risk_level='high' THEN CASE l.locale WHEN 'de' THEN 'Sofort stoppen bei Schmerzen, Kontrollverlust, beschädigtem Gerät oder unsicherer Landung; nur einzeln und mit direkter Aufsicht.' ELSE 'Stop for pain, loss of control, damaged equipment or an unsafe landing; one athlete at a time under direct supervision.' END ELSE CASE l.locale WHEN 'de' THEN 'Bei Schmerzen, Schwindel oder unsicherem Untergrund abbrechen; Belastung so wählen, dass saubere Wiederholungen möglich bleiben.' ELSE 'Stop for pain, dizziness or unsafe footing; choose a workload that allows clean repetitions.' END END,
  CASE WHEN e.category='running' THEN CASE l.locale WHEN 'de' THEN 'Ruhiger Oberkörper, lockere Arme, leise Schritte und ein Tempo, bei dem die Vorgabe kontrolliert eingehalten wird.' ELSE 'Quiet torso, relaxed arms, light steps and a pace that keeps the interval controlled.' END ELSE CASE l.locale WHEN 'de' THEN 'Bewegung bleibt schmerzfrei und kontrolliert; Körperposition und Gerät bleiben während jeder Wiederholung stabil.' ELSE 'Movement stays pain-free and controlled; body position and equipment remain stable throughout each repetition.' END END,
  CASE WHEN e.risk_level='high' THEN '3–5 kontrollierte Versuche' ELSE '2 Runden mit 6–8 sauberen Wiederholungen oder 20 Sekunden' END,
  CASE WHEN e.category='running' THEN '10–20 Minuten locker, Sprechtempo' ELSE '3 Runden mit 8–12 Wiederholungen oder 30 Sekunden' END,
  CASE WHEN e.category='running' THEN '4–6 Intervalle; zügig, aber ohne Sprintzwang' ELSE '3–4 Runden mit 10–15 Wiederholungen; Technik bleibt unverändert' END,
  CASE l.locale WHEN 'de' THEN 'Zwischen Sätzen 30–60 Sekunden pausieren; bei Technik- oder Hindernisarbeit vollständig erholen.' ELSE 'Rest 30–60 seconds between sets; recover fully for skill and obstacle work.' END,
  CASE l.locale WHEN 'de' THEN 'Bewegungsweg verkürzen, Tempo senken oder eine stabile Unterstützung verwenden.' ELSE 'Shorten the range, slow down or use stable support.' END,
  CASE l.locale WHEN 'de' THEN 'Bewegung in kontrolliertem Tempo und mit freigegebener Standardausführung.' ELSE 'Use a controlled pace and the approved standard execution.' END,
  CASE l.locale WHEN 'de' THEN 'Nur eine Schwierigkeit steigern: Weg, Dauer, Tempo oder Koordination; nie gleichzeitig Höhe und Ermüdung.' ELSE 'Increase only one challenge: distance, duration, pace or coordination; never height and fatigue together.' END,
  CASE l.locale WHEN 'de' THEN 'Als Spiel oder kurze Technikaufgabe mit niedriger Höhe, weichem Tempo und häufigen Erfolgen gestalten; keine erzwungenen Wiederholungen.' ELSE 'Use as a game or short skill task at low height and easy pace with frequent success; do not force repetitions.' END,
  CASE WHEN e.category IN ('ocr-skill','grip-rig') THEN CASE l.locale WHEN 'de' THEN 'Voraussetzung: sicherer Auf- und Abstieg, kontrollierter Griff und Verständnis des Stoppsignals.' ELSE 'Prerequisite: safe mounting and dismounting, controlled grip and understanding the stop signal.' END ELSE CASE l.locale WHEN 'de' THEN 'Keine besondere Voraussetzung; Grundbewegung schmerzfrei ausführen können.' ELSE 'No special prerequisite; athlete can perform the basic movement without pain.' END END,
  CASE l.locale WHEN 'de' THEN 'Bei fehlendem oder gesperrtem Gerät auf eine bodennahe, kontrollierte Variante derselben Bewegungsrichtung wechseln.' ELSE 'If equipment is unavailable or closed, use a low-level controlled variation of the same movement pattern.' END,
  CASE WHEN e.risk_level='high' THEN 'advanced' WHEN e.risk_level='medium' THEN 'intermediate' ELSE 'beginner' END,
  CASE WHEN e.risk_level='high' OR e.category IN ('ocr-skill','grip-rig') THEN 'direct' WHEN e.risk_level='medium' THEN 'increased' ELSE 'normal' END,
  e.space_requirement, e.setup_seconds, e.transition_seconds, e.station_capacity
FROM exercises e CROSS JOIN (VALUES ('de'),('en')) l(locale)
WHERE e.seed_key IS NOT NULL;

-- Three clear, translated coaching steps per seeded exercise.
INSERT INTO exercise_execution_steps
SELECT e.id,l.locale,n.step_order,
  CASE l.locale WHEN 'de' THEN CASE n.step_order WHEN 1 THEN 'Höre die kurze Demonstration an und prüfe Startposition sowie Bewegungsweg.' WHEN 2 THEN 'Beginne auf das Signal und bewege dich kontrolliert durch den vollständigen, schmerzfreien Bewegungsweg.' ELSE 'Beende die Wiederholung ruhig, prüfe deine Haltung und starte erst dann erneut.' END
  ELSE CASE n.step_order WHEN 1 THEN 'Watch the brief demonstration and check the start position and movement path.' WHEN 2 THEN 'Start on the signal and move under control through the full, pain-free range.' ELSE 'Finish the repetition calmly, check your position and then begin again.' END END
FROM exercises e CROSS JOIN (VALUES ('de'),('en')) l(locale) CROSS JOIN (VALUES (1),(2),(3)) n(step_order)
WHERE e.seed_key IS NOT NULL;

INSERT INTO exercise_coaching_cues
SELECT e.id,l.locale,n.cue_order,CASE l.locale WHEN 'de' THEN n.de ELSE n.en END
FROM exercises e CROSS JOIN (VALUES ('de'),('en')) l(locale)
CROSS JOIN (VALUES (1,'Ruhig starten','Start smoothly'),(2,'Sauber vor schnell','Quality before speed'),(3,'Atme weiter','Keep breathing')) n(cue_order,de,en)
WHERE e.seed_key IS NOT NULL;

INSERT INTO exercise_common_mistakes
SELECT e.id,l.locale,n.mistake_order,CASE l.locale WHEN 'de' THEN n.de ELSE n.en END,
  CASE l.locale WHEN 'de' THEN n.fix_de ELSE n.fix_en END
FROM exercises e CROSS JOIN (VALUES ('de'),('en')) l(locale)
CROSS JOIN (VALUES
 (1,'Tempo wird zu hoch und die Haltung kippt.','Tempo senken und nur saubere Wiederholungen zählen.','Pace gets too fast and posture breaks down.','Slow down and count only clean repetitions.'),
 (2,'Blick oder Aufmerksamkeit verlässt den Bewegungsweg.','Warte kurz, richte den Blick neu aus und setze kontrolliert fort.','Attention leaves the movement path.','Pause, refocus and continue under control.')
) n(mistake_order,de,fix_de,en,fix_en)
WHERE e.seed_key IS NOT NULL;

-- Source migration: 005_running_seed_guidance.sql
CREATE TABLE IF NOT EXISTS exercise_running_guidance (
  exercise_id UUID PRIMARY KEY REFERENCES exercises(id),
  running_kind VARCHAR NOT NULL CHECK (running_kind IN ('technique','endurance','interval','transition','team')),
  intensity_rpe_min SMALLINT NOT NULL CHECK (intensity_rpe_min BETWEEN 1 AND 10),
  intensity_rpe_max SMALLINT NOT NULL CHECK (intensity_rpe_max BETWEEN intensity_rpe_min AND 10),
  intensity_de VARCHAR NOT NULL,
  intensity_en VARCHAR NOT NULL,
  technique_focus_de VARCHAR NOT NULL,
  technique_focus_en VARCHAR NOT NULL
);

CREATE TEMP TABLE running_seed_guidance AS SELECT * FROM (VALUES
('easy-run','endurance',2,4,'RPE 2–4/10: Gesprächstempo; ganze Sätze bleiben möglich.','RPE 2–4/10: conversational pace; full sentences remain possible.','Halte die Schritte locker und gleichmäßig; beende den Lauf mit Reserve.','Keep steps relaxed and even; finish with some reserve.'),
('run-walk-interval','endurance',2,5,'RPE 2–5/10: laufe locker, gehe so lange, bis die Atmung wieder ruhig ist.','RPE 2–5/10: jog easily and walk until breathing settles.','Wechsle an festen Zeit- oder Streckenpunkten; beschleunige nicht, um Gehpausen zu überspringen.','Switch at set time or distance points; do not speed up to skip walk breaks.'),
('tempo-run','endurance',5,7,'RPE 5–7/10: zügig und gleichmäßig, kurze Sätze sind noch möglich; kein Sprint.','RPE 5–7/10: comfortably hard and steady; short phrases are possible, no sprinting.','Finde nach dem Einlaufen ein gleichmäßiges Tempo und halte es ohne Endspurt.','After warming up, settle into an even pace and hold it without a finishing sprint.'),
('fartlek','interval',3,7,'RPE 3–7/10: locker in Erholungsabschnitten, zügig in den Belastungen.','RPE 3–7/10: easy during recovery, brisk during work periods.','Wechsle nach klaren Landmarken oder Zeitfenstern; jede schnelle Passage bleibt technisch kontrolliert.','Alternate at clear landmarks or timed windows; keep every faster segment technically controlled.'),
('short-intervals','interval',6,8,'RPE 6–8/10: kurze zügige Abschnitte; erhole dich vollständig genug für gleichmäßige Wiederholungen.','RPE 6–8/10: short brisk efforts; recover enough to keep repetitions even.','Nutze 10–30 Sekunden oder 60–150 m; brich die Serie ab, wenn Tempo oder Haltung deutlich zerfallen.','Use 10–30 seconds or 60–150 m; end the set if pace or posture clearly breaks down.'),
('long-intervals','interval',5,7,'RPE 5–7/10: längere kontrollierte Abschnitte, deutlich unter maximalem Tempo.','RPE 5–7/10: longer controlled efforts, well below maximum pace.','Arbeite etwa 2–5 Minuten und trabe oder gehe 1–3 Minuten; halte die Wiederholungen gleichmäßig.','Work for about 2–5 minutes and jog or walk for 1–3 minutes; keep repetitions even.'),
('hill-repeats','interval',5,7,'RPE 5–7/10 bergauf; gehe locker bergab zurück und starte erst erholt.','RPE 5–7/10 uphill; walk down easily and restart recovered.','Wähle einen mäßigen, griffigen Hang; verkürze bergauf den Schritt und vermeide aggressives Abstoßen.','Choose a moderate grippy slope; shorten the uphill stride and avoid aggressive push-off.'),
('shuttle-run','interval',5,7,'RPE 5–7/10: kontrollierte Pendelläufe mit vollständigem Abbremsen an jeder Linie.','RPE 5–7/10: controlled shuttles with a full deceleration at each line.','Setze vor der Linie mehrere kurze Bremsschritte; drehe erst stabil und laufe dann zurück.','Take several short braking steps before the line; turn only when stable, then run back.'),
('strides','technique',4,6,'RPE 4–6/10: 10–20 Sekunden flüssig steigern, schnell aber entspannt; lange gehen zwischen Läufen.','RPE 4–6/10: build smoothly for 10–20 seconds, fast but relaxed; walk fully between runs.','Steigere über die Strecke allmählich und rolle locker aus; kein maximaler Sprint.','Build gradually across the distance and ease off smoothly; do not sprint maximally.'),
('acceleration-run','technique',4,7,'RPE 4–7/10: beginne leicht und steigere in mehreren Schritten, ohne abrupten Start.','RPE 4–7/10: start easy and build over several steps, with no sudden launch.','Drücke den Boden zunehmend kräftig nach hinten; halte Kopf und Rumpf ruhig.','Push the ground progressively backward; keep head and torso quiet.'),
('deceleration-drill','technique',2,5,'RPE 2–5/10: Anlauf zunächst locker; steigere erst, wenn das Abbremsen sicher gelingt.','RPE 2–5/10: begin with an easy approach; increase only when braking is secure.','Bremse über mehrere Schritte, senke den Körperschwerpunkt leicht und halte Knie über den Füßen.','Brake over several steps, lower your centre of mass slightly and keep knees aligned over feet.'),
('a-skip','technique',2,4,'RPE 2–4/10: kurze Technikdurchgänge mit Geh-Erholung; Höhe ist kein Ziel.','RPE 2–4/10: short technique bouts with walking recovery; height is not the goal.','Heb ein Knie locker an, setze den Fuß unter dem Körper auf und koordiniere den Gegenarm.','Lift one knee loosely, place the foot under the body and coordinate the opposite arm.'),
('b-skip','technique',2,4,'RPE 2–4/10: kurze Technikdurchgänge; reduziere die Bewegung auf A-Skip, wenn die Kontrolle fehlt.','RPE 2–4/10: short technique bouts; reduce to A-skip if control is lost.','Führe den Unterschenkel nur sanft nach vorn und setze aktiv unter dem Körperschwerpunkt auf.','Extend the lower leg gently and actively place the foot under your centre of mass.'),
('ankling','technique',2,4,'RPE 2–4/10: kurze lockere Bahnen; kein schmerzhaftes oder maximales Federn.','RPE 2–4/10: short relaxed runs; avoid painful or maximal bouncing.','Laufe mit kleinen Schritten aus dem Sprunggelenk und halte Knie und Rumpf entspannt.','Use small ankle-driven steps and keep knees and torso relaxed.'),
('running-high-knees','technique',2,5,'RPE 2–5/10: Techniktempo, bei dem Haltung und Rhythmus sauber bleiben.','RPE 2–5/10: use a technical pace that preserves posture and rhythm.','Heb die Knie nur so weit, wie das Becken stabil bleibt; lande leise unter dem Körper.','Lift knees only as high as the pelvis stays stable; land quietly under the body.'),
('running-butt-kicks','technique',2,5,'RPE 2–5/10: kurze lockere Abschnitte, keine erzwungene Fersenhöhe.','RPE 2–5/10: short relaxed bouts; do not force heel height.','Lass die Ferse locker nach hinten schwingen und führe das Knie wieder nach vorn.','Let the heel swing loosely back and then drive the knee forward again.'),
('bounding','technique',4,6,'RPE 4–6/10: wenige federnde Schritte mit voller Erholung; abbrechen, wenn Landungen laut werden.','RPE 4–6/10: use a few springing steps with full recovery; stop if landings become loud.','Nutze einen elastischen, nicht maximalen Abdruck und lande stabil unter dem Körper.','Use a springy but submaximal push-off and land steadily under the body.'),
('cadence-run','technique',3,5,'RPE 3–5/10: komfortables Lauftempo; ändere die Schrittfrequenz nur leicht.','RPE 3–5/10: comfortable running effort; adjust cadence only slightly.','Nutze einen kurzen Zeitabschnitt zum Zählen und verkürze bei höherer Frequenz den Schritt.','Count for a short timed segment and shorten the stride when cadence rises.'),
('cone-slalom-run','technique',3,5,'RPE 3–5/10: kontrolliertes Tempo; genügend Abstand zwischen Hütchen und Läufern.','RPE 3–5/10: controlled pace; leave enough space between cones and runners.','Blicke zur nächsten freien Lücke, lenke mit kleinen Schritten und schneide keine Kurve eng ab.','Look to the next open gap, steer with small steps and do not cut turns tightly.'),
('lateral-shuffle-run','technique',2,4,'RPE 2–4/10: kurze kontrollierte Bahnen; Füße kreuzen sich nicht.','RPE 2–4/10: use short controlled lanes; do not cross your feet.','Bleib seitlich ausgerichtet, halte die Knie weich und stoße gleichmäßig vom äußeren Fuß ab.','Stay side-on, keep knees soft and push evenly from the outside foot.'),
('relay-run','team',3,6,'RPE 3–6/10: Staffeln als kontrollierte Teamaufgabe; jede Person startet erst bei freier Bahn.','RPE 3–6/10: treat the relay as controlled teamwork; each runner starts only when the lane is clear.','Markiere eine Übergabezone; übergib ruhig in die Hand und vermeide Gegenverkehr.','Mark a handover zone; pass calmly into the hand and prevent opposing traffic.'),
('trail-run','endurance',3,6,'RPE 3–6/10: richte das Tempo nach Untergrund und Sicht; Gehen an unsicheren Stellen ist passend.','RPE 3–6/10: match effort to footing and visibility; walking on unsafe sections is appropriate.','Blicke einige Schritte voraus, verkürze den Schritt auf losem Boden und halte Abstand.','Look a few steps ahead, shorten stride on loose ground and leave space.'),
('run-exercise-100m','interval',3,6,'RPE 3–6/10: 100 m locker laufen, dann die angekündigte Übung in ruhiger Qualität ausführen.','RPE 3–6/10: run 100 m easily, then perform the announced exercise with calm quality.','Lege Übung und Wiederholungszahl vor dem Start fest; halte die Laufstrecke frei und zähle die Gesamtdosis.','Set the exercise and reps before starting; keep the route clear and count total volume.'),
('run-obstacle-transition','transition',3,6,'RPE 3–6/10: laufe den Anlauf kontrolliert und gehe vor dem Hindernis in eine sichere Arbeitsgeschwindigkeit.','RPE 3–6/10: approach at a controlled pace and slow to a safe working speed before the obstacle.','Markiere Brems- und Wartezone; erst starten, wenn das Hindernis frei und freigegeben ist.','Mark a braking and waiting zone; start only when the obstacle is clear and approved.'),
('stairs-run','interval',3,6,'RPE 3–6/10: zügig, aber kontrolliert aufsteigen; für den Abstieg gehen und nicht überholen.','RPE 3–6/10: climb briskly but under control; walk down and do not overtake.','Nutze eine freie Treppe mit griffigen Stufen; setze jeden Schritt sicher auf und laufe nicht abwärts.','Use clear stairs with grippy steps; place each foot securely and never run down.')
) AS values_table(seed_key,running_kind,rpe_min,rpe_max,intensity_de,intensity_en,technique_de,technique_en);

INSERT INTO exercise_running_guidance
SELECT e.id,g.running_kind,g.rpe_min,g.rpe_max,
  g.intensity_de,g.intensity_en,g.technique_de,g.technique_en
FROM running_seed_guidance g
JOIN exercises e ON e.seed_key=g.seed_key;

UPDATE exercise_details d SET
  purpose=CASE l.locale WHEN 'de' THEN t.name || ': ' || g.technique_focus_de ELSE t.name || ': ' || g.technique_focus_en END,
  setup=CASE WHEN g.running_kind IN ('technique','interval','transition')
    THEN CASE l.locale WHEN 'de' THEN 'Markiere eine freie, ebene Bahn mit Start- und Endpunkt; trenne Wartebereich und Laufrichtung.' ELSE 'Mark a clear, level lane with start and finish points; separate the waiting area from the running direction.' END
    ELSE CASE l.locale WHEN 'de' THEN 'Lege eine passende, freie Route fest; prüfe Untergrund, Sicht und sichere Wendepunkte.' ELSE 'Choose an appropriate clear route; check footing, visibility and safe turn points.' END END,
  start_position=CASE l.locale WHEN 'de' THEN 'Stehe hinter der Startmarkierung, prüfe die freie Bahn und beginne nach dem Signal im vorgegebenen Rhythmus.' ELSE 'Stand behind the start marker, check the clear lane and begin on the signal at the prescribed rhythm.' END,
  tempo_cue=CASE l.locale WHEN 'de' THEN g.intensity_de || ' ' || g.technique_focus_de ELSE g.intensity_en || ' ' || g.technique_focus_en END,
  quality_criteria=CASE l.locale WHEN 'de' THEN 'Die Wiederholungen bleiben gleichmäßig; Laufhaltung und ' || g.technique_focus_de || ' bleiben auch zum Ende kontrolliert.' ELSE 'Repetitions remain even; running posture and ' || g.technique_focus_en || ' stay controlled through the finish.' END,
  beginner_prescription=CASE l.locale WHEN 'de' THEN CASE g.running_kind WHEN 'technique' THEN '3 × 15–20 m; gehend zurück, Technik vor Tempo.' WHEN 'endurance' THEN '8–12 Minuten am unteren Ende der RPE-Vorgabe; Gehpausen erlaubt.' WHEN 'team' THEN '2 kurze Läufe pro Person; erst bei freier Bahn starten.' ELSE '4 kurze Durchgänge am unteren Ende der RPE-Vorgabe; vollständig erholen.' END ELSE CASE g.running_kind WHEN 'technique' THEN '3 × 15–20 m; walk back, technique before speed.' WHEN 'endurance' THEN '8–12 minutes at the lower end of the RPE range; walk breaks allowed.' WHEN 'team' THEN '2 short runs per person; start only when the lane is clear.' ELSE '4 short bouts at the lower end of the RPE range; recover fully.' END END,
  standard_prescription=CASE l.locale WHEN 'de' THEN g.intensity_de || ' 4–6 Durchgänge; für Technik 15–30 m, für Intervalle 30–120 Sekunden.' ELSE g.intensity_en || ' 4–6 bouts; use 15–30 m for drills and 30–120 seconds for intervals.' END,
  advanced_prescription=CASE l.locale WHEN 'de' THEN 'Bis zu 6–8 Durchgänge oder längere Belastung; nur steigern, wenn alle Wiederholungen technisch gleichmäßig bleiben.' ELSE 'Build to 6–8 bouts or a longer effort; progress only while all repetitions remain technically even.' END,
  work_rest_guidance=CASE l.locale WHEN 'de' THEN g.intensity_de || ' Bei Technik und kurzen Intervallen mindestens 1:2 Belastung zu Erholung; bei Dauerläufen bleibt die Belastung durchgehend locker.' ELSE g.intensity_en || ' For drills and short intervals, allow at least a 1:2 work-to-recovery ratio; keep continuous runs easy throughout.' END
FROM exercise_running_guidance g
JOIN exercises e ON e.id=g.exercise_id
JOIN exercise_translations t ON t.exercise_id=e.id
JOIN (VALUES ('de'),('en')) l(locale) ON true
WHERE d.exercise_id=e.id AND t.locale=d.locale AND l.locale=d.locale;

-- Replace generic seed steps with a route-specific run sequence and the actual
-- technique target for that exercise, in both supported languages.
DELETE FROM exercise_execution_steps s USING exercise_running_guidance g WHERE s.exercise_id=g.exercise_id;
INSERT INTO exercise_execution_steps
SELECT g.exercise_id,l.locale,n.step_order,
  CASE l.locale WHEN 'de' THEN CASE n.step_order
    WHEN 1 THEN 'Prüfe die markierte Laufbahn und beginne erst, wenn sie frei ist; wärme dich mit lockerem Laufen und dynamischen Bewegungen auf.'
    WHEN 2 THEN g.technique_focus_de || ' ' || g.intensity_de
    ELSE 'Beende den Abschnitt kontrolliert, gehe zur Erholung zurück und starte die nächste Wiederholung erst, wenn die geforderte Technik wieder möglich ist.' END
  ELSE CASE n.step_order
    WHEN 1 THEN 'Check the marked running lane and start only when it is clear; warm up with easy running and dynamic movement.'
    WHEN 2 THEN g.technique_focus_en || ' ' || g.intensity_en
    ELSE 'Finish under control, walk to recover and begin the next repetition only when the required technique is available again.' END END
FROM exercise_running_guidance g CROSS JOIN (VALUES ('de'),('en')) l(locale) CROSS JOIN (VALUES (1),(2),(3)) n(step_order);

UPDATE exercise_coaching_cues c SET cue=CASE c.locale
  WHEN 'de' THEN CASE c.cue_order WHEN 1 THEN 'Ruhig anlaufen' WHEN 2 THEN 'Schritt und Tempo kontrollieren' ELSE 'Erst erholt wiederholen' END
  ELSE CASE c.cue_order WHEN 1 THEN 'Start smoothly' WHEN 2 THEN 'Control stride and pace' ELSE 'Repeat when recovered' END END
FROM exercise_running_guidance g WHERE c.exercise_id=g.exercise_id;

UPDATE exercise_common_mistakes m SET
  mistake=CASE m.locale WHEN 'de' THEN 'Tempo oder Schrittlänge steigt so weit, dass ' || g.technique_focus_de || ' verloren geht.' ELSE 'Pace or stride length increases until ' || g.technique_focus_en || ' is lost.' END,
  correction=CASE m.locale WHEN 'de' THEN 'Tempo senken, Strecke verkürzen und erst wieder steigern, wenn die Technik stabil bleibt.' ELSE 'Reduce pace, shorten the distance and progress only when technique stays stable.' END
FROM exercise_running_guidance g WHERE m.exercise_id=g.exercise_id AND m.mistake_order=1;

DROP TABLE running_seed_guidance;

-- Source migration: 006_obstacle_seed_guidance.sql
CREATE TABLE IF NOT EXISTS exercise_obstacle_guidance (
  exercise_id UUID NOT NULL REFERENCES exercises(id),
  locale VARCHAR NOT NULL CHECK (locale IN ('de','en')),
  equipment_configuration VARCHAR NOT NULL,
  prerequisites VARCHAR NOT NULL,
  approach VARCHAR NOT NULL,
  execution VARCHAR NOT NULL,
  exit_reset VARCHAR NOT NULL,
  fallback_exercise VARCHAR NOT NULL,
  station_capacity SMALLINT NOT NULL CHECK (station_capacity > 0),
  clear_zone_metres DECIMAL(5,2) NOT NULL CHECK (clear_zone_metres > 0),
  PRIMARY KEY (exercise_id, locale)
);

CREATE TEMP TABLE obstacle_seed_guidance AS SELECT * FROM (VALUES
('bear-crawl',2.0,'Freie ebene Bahn, rutschfester Boden, kurze markierte Wendestrecke.','Clear level lane, non-slip surface and a short marked turn.','Kann sicher auf Hände und Füße gehen und auf Signal stoppen.','Can move safely on hands and feet and stop on cue.','Starte im Vierfüßlerstand, Hände unter Schultern, Knie knapp über dem Boden.','Begin on all fours with hands under shoulders and knees just off the floor.','Bewege gegenüberliegende Hand und Fuß in kleinen Schritten; halte Rücken ruhig und Blick zum Boden.','Move opposite hand and foot in short steps; keep back steady and eyes on the floor.','Stoppe vor der Markierung, setze die Knie ab und gehe aus der Bahn.','Stop before the marker, lower knees and leave the lane.','Bear-Plank halten oder kurze Vierfüßler-Schritte am Boden.','Hold a bear plank or take short all-fours steps on the floor.'),
('low-crawl',2.0,'Ebene, saubere Matte oder Rasenbahn; Länge kurz halten und Wendemarke setzen.','Use a clean level mat or grass lane; keep it short and mark the turn.','Kann sicher in Bauchlage abstützen und ohne Atemnot aufstehen.','Can support themselves safely prone and rise without breathlessness.','Lege dich hinter die Startlinie, Ellbogen nah am Körper, Blick nach vorn-unten.','Lie behind the start line with elbows close and eyes forward-down.','Ziehe dich mit Unterarmen kontrolliert vor; halte Becken tief und bewege dich nur so weit, dass Atmung frei bleibt.','Pull forward under control with forearms; keep hips low and move only while breathing stays free.','Stoppe an der Markierung, drehe dich auf die Seite und steh über den Vierfüßlerstand auf.','Stop at the marker, roll to your side and rise through all fours.','Vierfüßler-Crawl mit höherem Becken oder kürzere Strecke.','Use a higher all-fours crawl or shorten the distance.'),
('army-crawl',2.0,'Ebene Matte oder weicher, geprüfter Rasen; keine Steine, scharfen Kanten oder Gegenstände im Weg.','Use a level mat or checked soft grass; remove stones, sharp edges and objects.','Kann sicher in Bauchlage liegen, sich abstützen und bei Bedarf sofort stoppen.','Can lie prone, support themselves and stop immediately if needed.','Lege dich flach hinter die Linie und prüfe, dass die gesamte Strecke frei ist.','Lie flat behind the line and check that the full lane is clear.','Ziehe dich abwechselnd mit Unterarm und gegenüberliegendem Bein vor; halte Kopf neutral und Tempo niedrig.','Pull forward using alternating forearm and opposite leg; keep head neutral and pace slow.','Beende an der Markierung, rolle auf die Seite und verlasse die Bahn gehend.','Finish at the marker, roll to your side and walk out of the lane.','Low-Crawl auf den Unterarmen ohne Beinzug oder normaler Vierfüßler-Crawl.','Use a forearm low crawl without leg drive or a regular all-fours crawl.'),
('crab-walk',2.0,'Ebene rutschfeste Fläche; Bahn frei von anderen Gruppen und niedrigen Hindernissen.','Use a level non-slip surface; keep the lane clear of other groups and low obstacles.','Kann sich schmerzfrei rückwärts auf Hände und Füße stützen.','Can support themselves backward on hands and feet without pain.','Setze dich, Hände hinter dem Körper, Füße hüftbreit und Finger seitlich oder nach vorn.','Sit with hands behind, feet hip-width apart and fingers turned sideways or forward.','Hebe das Becken nur so weit, dass du stabil bleibst; gehe kontrolliert Hand und Fuß im Wechsel.','Lift hips only as high as stable; travel by alternating hand and foot under control.','Setze das Becken ab und stehe über eine seitliche Drehung auf.','Lower hips and stand via a side turn.','Becken am Boden lassen und kurze Hand-Fuß-Schritte üben.','Keep hips on the floor and practise short hand-foot steps.'),
('wall-stepover-low',3.0,'Nur freigegebene niedrige, feste Wand mit sicherem Tritt und freier, weicher Landefläche auf beiden Seiten.','Use only an approved low stable wall with a secure step and clear soft landing on both sides.','Kann kontrolliert aufsteigen und absteigen; kennt Stoppzeichen und Wartelinie.','Can step up and down under control; knows stop signal and waiting line.','Warte hinter der Linie, prüfe Wand und Landefläche, gehe frontal ohne Anlauf heran.','Wait behind the line, check wall and landing, approach front-on without a run-up.','Setze einen Fuß auf den vorgesehenen Tritt, drücke dich kontrolliert hoch und steige einzeln über die Wand.','Place one foot on the designated step, rise under control and step over one at a time.','Lande mit beiden Füßen stabil, entferne dich seitlich und gib die Bahn frei.','Land with both feet stable, move aside and clear the lane.','Niedriger Step-up über eine Bodenmarkierung oder niedrige feste Bank.','Use a low step-up over a floor marker or stable low bench.'),
('wall-vault-basic',4.0,'Nur geprüfte niedrige Vereinswand mit geeigneten Griffpunkten, Matten/Landezone und direkter Traineraufsicht.','Use only a checked low club wall with suitable handholds, mats/landing zone and direct coach supervision.','Beherrscht Step-over und kontrollierten Stütz am Boden; kann sicher absteigen.','Has mastered step-over and controlled floor support; can dismount safely.','Warte bis die Wand frei ist; nähere dich gehend und lege die Hände auf die markierten stabilen Griffe.','Wait until the wall is clear; walk in and place hands on marked stable holds.','Übe zuerst den Stütz; verlagere Gewicht über die Hände und führe ein Bein nach dem anderen über die niedrige Wand.','Practise support first; shift weight through hands and bring one leg at a time over the low wall.','Lande auf beiden Füßen, stabilisiere dich und steige aus der Zone.','Land on both feet, stabilise and leave the zone.','Wand-Step-over mit Fußstütze oder niedriger Banküberstieg.','Use a wall step-over with foot support or a low bench step-over.'),
('incline-wall-run',4.0,'Gering geneigte, rutschfeste und freigegebene Trainingsfläche; freie Anlauf-, Auslauf- und Seitenzone.','Use an approved gently inclined non-slip surface with clear approach, run-out and side zones.','Kann auf ebenem Boden abbremsen und sicher gehen; beginnt ohne Sprung- oder Kletterversuch.','Can decelerate on level ground and walk safely; no jumping or climbing attempt at first.','Starte aus kurzem Geh- oder Jogginganlauf; Trainer steht seitlich außerhalb der Laufspur.','Start from a short walk or jog; coach stands to the side outside the lane.','Setze einen Fuß nach dem anderen auf die Schräge, halte den Körper nah an der Fläche und steige nur bis zur markierten niedrigen Höhe.','Place one foot at a time on the incline, stay close to the surface and climb only to the marked low height.','Steige kontrolliert zurück oder über den ausgewiesenen seitlichen Ausgang ab; nicht abspringen.','Descend under control or use the marked side exit; do not jump down.','Step-ups an einer niedrigen schrägen Fläche ohne Anlauf.','Use step-ups on a low incline without a run-up.'),
('cargo-net-climb',4.0,'Niedrig eingestelltes, verankertes und geprüftes Netz; Matten oder geeigneter Fallschutz und abgesperrte Fallzone.','Use a low, anchored and inspected net; add mats or suitable fall protection and close the fall zone.','Kann drei sichere Kontaktpunkte halten und den Abstieg kontrolliert ausführen.','Can maintain three secure points of contact and descend under control.','Warte seitlich hinter der Markierung; prüfe Verankerung, Netzspannung und freie Fallzone.','Wait to the side behind the marker; check anchors, net tension and clear fall zone.','Klettere aufrecht mit Händen und Füßen abwechselnd; halte stets drei Kontaktpunkte und nutze nur die freigegebene Höhe.','Climb upright by alternating hands and feet; keep three points of contact and stay within the approved height.','Steige dieselbe Route rückwärts kontrolliert ab; springe niemals herunter.','Descend the same route under control; never jump down.','Bodennahes Netzqueren oder Kletterbewegung an einer niedrigen Sprossenwand.','Use a ground-level net traverse or climb on a low ladder wall.'),
('cargo-net-traverse',4.0,'Seitlich niedriges, straff verankertes Netz mit Fallschutz; Ein- und Ausstieg markieren, Fallzone sperren.','Use a low side net secured tautly with fall protection; mark entry and exit and close fall zone.','Kann stabil am Netz stehen und jederzeit zur sicheren Seite zurückkehren.','Can stand steadily at the net and return to the safe side at any time.','Warte bis die vorherige Person vollständig ausgestiegen ist; prüfe Netz und Landebereich.','Wait until the previous person has fully exited; check net and landing area.','Bewege dich seitlich mit Händen und Füßen über benachbarte Maschen; löse immer nur einen Kontaktpunkt.','Move sideways using hands and feet on adjacent squares; release only one contact point at a time.','Erreiche den markierten Ausgang und steige dort kontrolliert ab.','Reach the marked exit and descend there under control.','Seitliches Gehen an einer niedrigen, stabilen Stange oder Bodenlinie.','Practise side steps along a low stable rail or floor line.'),
('over-under',3.0,'Niedrige stabile Hindernisse mit großem Abstand; keine scharfen Kanten, Stolperfallen oder Gegenverkehr.','Use low stable obstacles with generous spacing; remove sharp edges, trip hazards and opposing traffic.','Kann sicher kriechen und über eine niedrige Markierung steigen.','Can crawl safely and step over a low marker.','Gehe die Bahn zuerst ab; benenne klar, welches Hindernis über- und welches unterquert wird.','Walk the lane first; clearly identify which obstacle is stepped over and which is crawled under.','Steige über niedrige Hindernisse, gehe danach unter der freien Stange hindurch; halte die Reihenfolge und Blick nach vorn.','Step over low obstacles, then crawl under the clear bar; keep sequence and look ahead.','Gehe nach der letzten Markierung aus der Bahn, wende außerhalb und kehre zurück.','Exit after the last marker, turn outside the lane and return.','Höhe reduzieren und nur steigen oder nur kriechen.','Lower the height and practise only stepping or only crawling.'),
('box-over',3.0,'Niedrige kippsichere Box oder Bank, rutschfester Boden und Matten; seitliche Ausstiegsfläche freihalten.','Use a low non-tipping box or bench, non-slip floor and mats; keep side exit clear.','Kann sicher stützen und kontrolliert auf niedrige Erhöhung auf- und absteigen.','Can support themselves and step on/off a low platform safely.','Stelle dich nah an die Box; prüfe Standfestigkeit und freie Landefläche, bevor du startest.','Stand close to the box; check stability and clear landing before starting.','Stütze die Hände auf, verlagere Gewicht kontrolliert und steige mit einem Bein nach dem anderen hinüber.','Place hands on the box, shift weight under control and step across one leg at a time.','Lande beidfüßig, richte dich auf und gehe seitlich aus dem Stationsbereich.','Land on both feet, stand tall and exit the station to the side.','Niedriger Step-over ohne Stütz oder seitlicher Step-up.','Use a lower step-over without support or a side step-up.'),
('rope-traverse',4.0,'Niedrig gespanntes, fest verankertes Seil über durchgehender Fallschutzfläche; direkte Aufsicht und freie Ausstiegszone.','Use a low taut anchored rope over continuous fall protection; provide direct supervision and clear exit.','Kann stabil hängen oder stützen und kennt Abbruchsignal sowie kontrollierten Abstieg.','Can hang or support steadily and knows the stop signal and controlled dismount.','Prüfe Anker und Seil; warte bis die gesamte Traverse frei ist und greife aus sicherem Stand.','Check anchors and rope; wait until traverse is clear and grip from a secure stance.','Bewege die Hände einzeln entlang des Seils; halte den Körper ruhig und nutze nur den niedrigen freigegebenen Abschnitt.','Move hands one at a time along the rope; keep body controlled and use only the approved low section.','Beende am markierten Ende und steige über die vorgesehene Seite ab, nicht abspringen.','Finish at the marked end and dismount on the designated side; do not jump.','Sitzender Seilzug am Boden oder kurzer unterstützter Hang an niedriger Stange.','Use a seated floor rope pull or a short assisted hang on a low bar.'),
('obstacle-burpee-penalty',2.0,'Ebene rutschfeste Fläche mit Abstand zur Laufspur; Burpee-Variante und Umfang vorher ansagen.','Use a level non-slip surface away from running lanes; explain the burpee version and dose first.','Kann schmerzfrei in die Hocke und wieder zum Stand kommen; Liegestütz ist keine Voraussetzung.','Can squat and stand without pain; a push-up is not required.','Gehe aus der Laufspur in den markierten Bereich und nimm eine stabile Standposition ein.','Move out of the running lane into the marked area and stand steadily.','Setze Hände ab, steige die Füße einzeln zurück, kehre einzeln zurück und richte dich ohne Sprung auf.','Place hands down, step feet back one at a time, step them in and stand without a jump.','Prüfe den freien Weg und gehe erst nach dem Signal zurück auf die Laufbahn.','Check the lane is clear and return only on the signal.','Erhöhte Hände auf Bank oder reine Kniebeuge ohne Bodenphase.','Use hands on a raised bench or a squat without the floor phase.'),
('rig-run-interval',4.0,'Kurze Laufstrecke plus niedriges freigegebenes Rig; getrennte Zu- und Abgänge, Aufsicht an der Station.','Combine a short run with a low approved rig; separate entry/exit routes and supervise station.','Kann kontrolliert laufen, sicher greifen und auf Aufforderung sofort absteigen.','Can run under control, grip safely and dismount immediately on request.','Erkläre Reihenfolge, Laufweg und Warteposition; starte nur bei freier Rig-Station.','Explain sequence, route and waiting position; start only when the rig station is clear.','Laufe locker bis zur Markierung, wechsle gehend zum Rig und führe nur die freigegebene Hang- oder Traversevariante aus.','Run easily to the marker, walk to the rig and perform only the approved hang or traverse variation.','Steige kontrolliert ab, bestätige freie Station und gehe zurück; halte die Runde bei Technikverlust an.','Dismount under control, confirm the station is clear and walk back; stop the round if technique is lost.','Lauf plus bodennahe Griffaufgabe oder lauf plus Seilzug im Sitzen.','Pair running with a ground-level grip task or seated rope pull.'),
('wall-run-transition',4.0,'Niedrige freigegebene Wand mit weicher Landefläche; Laufspur endet vor Wartezone und Wandbereich.','Use an approved low wall with soft landing; end the running lane before the waiting and wall zone.','Kann auf ebener Strecke abbremsen und eine niedrige Wand sicher übersteigen.','Can decelerate on level ground and step over a low wall safely.','Laufe kontrolliert zur Bremsmarkierung, reduziere Tempo und warte bis die Wand frei ist.','Run under control to the braking marker, slow down and wait until the wall is clear.','Gehe an die Wand und übersteige sie mit der geübten niedrigen Variante; kein Anlauf direkt in den Sprung.','Walk to the wall and step over using the practised low variation; do not sprint into a jump.','Lande stabil, verlasse die Landefläche und setze den Lauf erst nach dem Ausgangspunkt fort.','Land steadily, clear the landing area and resume running only beyond the exit marker.','Lauf-Bremsübung plus niedriger Step-over als getrennte Aufgaben.','Practise running deceleration and a low step-over as separate tasks.'),
('crawl-run-transition',3.0,'Ebene weiche Crawlmatte an einer geraden, getrennten Laufspur; Ein- und Ausstieg markieren.','Place a level soft crawl mat beside a straight separate running lane; mark entry and exit.','Kann kontrolliert kriechen, aufstehen und vor der Laufspur warten.','Can crawl under control, stand up and wait before entering the running lane.','Beende den Lauf vor der Matte und warte auf freie Crawlbahn.','Finish the run before the mat and wait until crawl lane is clear.','Krieche die kurze markierte Strecke, stehe außerhalb der Laufspur auf und orientiere dich neu.','Crawl the short marked lane, stand outside the running route and reorient.','Gehe bis zur Startmarkierung und beginne den nächsten Laufabschnitt erst auf Signal.','Walk to the start marker and begin the next running segment only on cue.','Kurze Gehstrecke plus Vierfüßlerbewegung, Lauf und Crawl zunächst getrennt.','Use a short walk and all-fours movement; practise running and crawling separately first.')
) AS v(seed_key,clear_zone_metres,setup_de,setup_en,prereq_de,prereq_en,approach_de,approach_en,execution_de,execution_en,exit_de,exit_en,fallback_de,fallback_en);

INSERT INTO exercise_obstacle_guidance
SELECT e.id,l.locale,
  CASE l.locale WHEN 'de' THEN v.setup_de ELSE v.setup_en END,
  CASE l.locale WHEN 'de' THEN v.prereq_de ELSE v.prereq_en END,
  CASE l.locale WHEN 'de' THEN v.approach_de ELSE v.approach_en END,
  CASE l.locale WHEN 'de' THEN v.execution_de ELSE v.execution_en END,
  CASE l.locale WHEN 'de' THEN v.exit_de ELSE v.exit_en END,
  CASE l.locale WHEN 'de' THEN v.fallback_de ELSE v.fallback_en END,
  1,v.clear_zone_metres
FROM obstacle_seed_guidance v
JOIN exercises e ON e.seed_key=v.seed_key
CROSS JOIN (VALUES ('de'),('en')) l(locale);

UPDATE exercise_details d SET
  setup=g.equipment_configuration,
  prerequisites=g.prerequisites,
  fallback_exercise=g.fallback_exercise,
  start_position=g.approach,
  finish_reset=g.exit_reset,
  quality_criteria=g.execution || ' ' || g.exit_reset,
  safety_notes=CASE WHEN e.risk_level='high'
    THEN CASE d.locale WHEN 'de' THEN 'Direkte Stationsaufsicht ist erforderlich. Gerät vor jedem Durchgang prüfen, Fall- und Landefläche freihalten und nur eine Person auf der Station zulassen. Sofort stoppen bei beschädigtem Gerät, Kontrollverlust oder unsicherem Abstieg.' ELSE 'Direct station supervision is required. Inspect equipment before each turn, keep fall and landing zones clear and allow one person on the station at a time. Stop for damaged equipment, loss of control or unsafe dismount.' END
    ELSE CASE d.locale WHEN 'de' THEN 'Trainer hält die Bahn frei, prüft die Fläche und lässt erst starten, wenn der vorherige Teilnehmende die Station verlassen hat.' ELSE 'Coach keeps the lane clear, checks the surface and allows a start only after the previous participant has left the station.' END END,
  supervision=CASE WHEN e.risk_level='high' THEN 'direct' ELSE 'increased' END,
  station_capacity=g.station_capacity
FROM exercise_obstacle_guidance g
JOIN exercises e ON e.id=g.exercise_id
WHERE d.exercise_id=e.id AND d.locale=g.locale;

DELETE FROM exercise_execution_steps s USING exercise_obstacle_guidance g WHERE s.exercise_id=g.exercise_id AND s.locale=g.locale;
INSERT INTO exercise_execution_steps
SELECT g.exercise_id,g.locale,n.step_order,
  CASE n.step_order WHEN 1 THEN g.approach WHEN 2 THEN g.execution ELSE g.exit_reset END
FROM exercise_obstacle_guidance g CROSS JOIN (VALUES (1),(2),(3)) n(step_order);

UPDATE exercise_common_mistakes m SET
  mistake=CASE m.locale WHEN 'de' THEN 'Der Teilnehmende startet, bevor die Station frei ist, oder überspringt die vorgesehene Annäherung.' ELSE 'The participant starts before the station is clear or skips the planned approach.' END,
  correction=CASE m.locale WHEN 'de' THEN 'Zur Warteposition zurückkehren, erst nach Freigabe starten und die Annäherung Schritt für Schritt ausführen.' ELSE 'Return to the waiting position, start only when cleared and follow the approach one step at a time.' END
FROM exercise_obstacle_guidance g
WHERE m.exercise_id=g.exercise_id AND m.locale=g.locale AND m.mistake_order=1;

DROP TABLE obstacle_seed_guidance;

-- Source migration: 007_grip_rig_seed_guidance.sql
CREATE TEMP TABLE grip_rig_seed_guidance AS SELECT * FROM (VALUES
('dead-hang',2.0,'Stabile niedrige Stange mit rutschfester Landefläche; Höhe erlaubt Absprung mit Füßen am Boden.','Use a stable low bar over non-slip flooring; set height so feet can reach the floor.','Kann den eigenen Griff sicher lösen und mit Bodenkontakt entlasten.','Can release grip safely and unload with feet on the floor.','Stelle dich unter die Stange, greife schulterbreit und halte die Füße zunächst am Boden.','Stand under the bar, grip at shoulder width and keep feet on the floor initially.','Verlagere nur so viel Gewicht in die Hände, wie du sicher halten kannst; halte kurz und atme ruhig.','Load only as much weight into the hands as you can hold safely; pause briefly and breathe calmly.','Setze die Füße ab, löse eine Hand nach der anderen und gehe aus der Matte.','Place feet down, release one hand at a time and leave the mat.','Teilhang mit Füßen am Boden oder kurzer Griff an niedriger Stange.','Use a partial hang with feet on the floor or a short grip on a low bar.'),
('active-hang',2.0,'Niedrige fest montierte Stange und freie rutschfeste Abstiegfläche; direkte Sicht der Trainerperson.','Use a securely fixed low bar and clear non-slip dismount area within coach view.','Kann sicher in den Hang ein- und aussteigen und Schulterbewegung kontrollieren.','Can enter and exit a hang safely and control shoulder movement.','Greife die Stange und beginne mit gestreckten Armen und entspannter Schulterposition.','Grip the bar and begin with straight arms and relaxed shoulders.','Ziehe Schulterblätter sanft nach unten, ohne die Ellbogen zu beugen; halte den Rumpf ruhig.','Gently draw shoulder blades down without bending elbows; keep torso steady.','Löse die aktive Spannung, setze Füße kontrolliert auf und steige ab.','Release active tension, place feet down under control and dismount.','Schulterblattbewegung im Stand mit Band oder Teilhang mit Fußstütze.','Practise standing scapular depression with a band or a foot-supported partial hang.'),
('towel-hang',2.0,'Zwei gleich lange, unbeschädigte Handtücher sicher über niedriger Stange fixieren; Matte darunter.','Secure two equal undamaged towels over a low bar; place a mat beneath.','Kann den Griff selbstständig lösen; beginnt mit belasteten Füßen.','Can release grip independently; start with feet bearing some weight.','Prüfe beide Tücher, greife sie gleich hoch und stelle die Füße unter die Stange.','Check both towels, grip at equal height and place feet beneath the bar.','Belaste den Tuchgriff schrittweise und halte den Körper ruhig; Dauer kurz halten.','Load the towel grip gradually and keep body still; keep the hold brief.','Setze Gewicht auf die Füße zurück und löse beide Tücher ohne Fallenlassen.','Transfer weight back to feet and release both towels without dropping.','Sitzender Tuchzug oder stehender Zug mit Füßen am Boden.','Use a seated towel pull or standing pull with feet on the floor.'),
('ring-hang',2.0,'Ringe gleich hoch, Anker geprüft und niedrig eingestellt; Matte und freie Abstiegfläche.','Set rings level, inspect anchors and keep them low; use a mat and clear dismount area.','Kann Stütz oder Teilhang kontrolliert halten und sicher absteigen.','Can hold a support or partial hang and dismount safely.','Greife beide Ringe, prüfe gleiche Höhe und beginne mit Füßen am Boden.','Grip both rings, check equal height and begin with feet on the floor.','Verlagere kontrolliert Gewicht in die Hände; halte Ringe nah am Körper und vermeide Pendeln.','Shift weight into hands under control; keep rings close and avoid swinging.','Setze die Füße auf und löse die Ringe nacheinander.','Place feet down and release rings one at a time.','Teilhang mit Fußkontakt oder Ringstütz mit elastischer Unterstützung.','Use a foot-supported partial hang or ring support with elastic assistance.'),
('ring-row',2.0,'Ringe sicher verankern und auf Brusthöhe einstellen; Boden frei und nicht rutschig.','Anchor rings securely at chest height; keep floor clear and non-slip.','Kann eine stabile Körperlinie in leichter Schräglage halten.','Can hold a stable body line at a shallow angle.','Greife die Ringe, gehe mit den Füßen vor und lehne dich nur leicht zurück.','Grip rings, walk feet forward and lean back only slightly.','Ziehe Brust zwischen die Ringe, halte Körper gerade und führe die Arme kontrolliert zurück.','Pull chest between rings, keep body straight and lower arms under control.','Stelle dich aufrecht, gehe zurück und löse die Ringe im Stand.','Stand upright, step back and release rings while standing.','Aufrechter Bandzug oder weniger Schräglage mit Füßen näher an den Ringen.','Use an upright band row or reduce the lean by moving feet closer to rings.'),
('ring-traverse',3.0,'Ringe niedrig, dicht genug für erreichbare Übergänge, Anker und Fallschutz geprüft; nur eine Person auf dem Abschnitt.','Set rings low and close enough for reachable transfers; inspect anchors and fall protection; one person per section.','Kann kontrolliert hängen, einzeln umgreifen und jederzeit sicher absteigen.','Can hang under control, move one hand at a time and dismount safely at any point.','Warte bis der Abschnitt frei ist; greife den ersten Ring aus stabilem Stand.','Wait until the section is clear; take the first ring from a stable stance.','Bewege eine Hand zum nächsten Ring, stabilisiere den Griff und folge erst dann mit der anderen.','Move one hand to the next ring, stabilise the grip and only then follow with the other.','Erreiche den Endmarker, setze Füße auf und gehe seitlich aus dem Fallbereich.','Reach the end marker, place feet down and leave the fall zone to the side.','Bodennahes Umgreifen an festen Griffen oder unterstütztes Ringhangeln.','Practise low hand transfers on fixed holds or assisted ring traversal.'),
('monkeybars-basic',3.0,'Niedrige geprüfte Sprossenleiter mit Matten; Einstieg und Ausstieg eindeutig markieren.','Use a low inspected monkey-bar ladder with mats; mark entry and exit clearly.','Kann sicher greifen und Sprosse für Sprosse mit sicherem Abstieg bewältigen.','Can grip safely and move rung by rung with a safe dismount.','Warte bis die Leiter frei ist; greife die erste Sprosse aus dem Stand.','Wait until the ladder is clear; reach the first rung from standing.','Greife jede nächste Sprosse einzeln; bewege dich langsam und halte den Körper ruhig.','Take each next rung one at a time; move slowly and keep body controlled.','Löse am Endmarker den Griff erst mit Bodenkontakt oder Trainerhilfe.','At the end marker release only with feet grounded or coach assistance.','Seitliches Hangeln an niedriger fester Stange mit Fußkontakt.','Use side transfers on a low fixed bar with feet supported.'),
('monkeybars-skip',3.0,'Niedrige Sprossen mit engem Abstand, Matten und direkter Aufsicht; keine ermüdete oder nasse Nutzung.','Use low bars with close rung spacing, mats and direct supervision; no fatigued or wet attempts.','Beherrscht mehrere normale Sprossenübergänge und kontrollierten Abstieg.','Has mastered several normal rung transfers and a controlled dismount.','Beginne an der ersten Sprosse mit beiden Händen stabil; Trainer bestätigt freien Bereich.','Start at the first rung with both hands secure; coach confirms the area is clear.','Überspringe höchstens eine Sprosse, greife zuerst sicher und verlagere Gewicht erst nach geschlossenem Griff.','Skip at most one rung, secure the grip first and transfer weight only after the hold is closed.','Beende vor Griffverlust am vorgesehenen Punkt und steige kontrolliert ab.','Finish before grip failure at the designated point and dismount under control.','Monkey Bars Basis ohne übersprungene Sprossen.','Use basic monkey bars without skipping rungs.'),
('lateral-bar-traverse',3.0,'Niedrige feste Querstrecke mit Matten und markierten Seiten; Station nacheinander nutzen.','Use a low fixed traverse with mats and marked sides; take turns one at a time.','Beherrscht den sicheren Teilhang und seitliches Umgreifen mit Fußhilfe.','Has mastered a safe partial hang and lateral hand transfer with foot support.','Greife die Stange seitlich und stelle Füße so, dass du jederzeit entlasten kannst.','Grip the bar side-on and position feet so you can unload at any time.','Löse immer nur eine Hand, setze sie seitlich um und stabilisiere vor dem nächsten Wechsel.','Release one hand at a time, move it sideways and stabilise before the next transfer.','Erreiche den Endmarker, setze Füße auf und steige zur markierten Seite ab.','Reach the end marker, place feet down and dismount on the marked side.','Seitliches Umgreifen im Teilhang mit dauerhaftem Fußkontakt.','Practise lateral transfers in a partial hang with continuous foot contact.'),
('rope-grip-hold',2.0,'Dickes unbeschädigtes Seil an niedrigem geprüften Anker; Matte, freier Stand und kein Kletterversuch.','Use a thick undamaged rope on a low inspected anchor; mat and clear stance; no climbing attempt.','Kann Griffkraft dosieren und vor Ermüdung selbstständig absetzen.','Can dose grip effort and release before fatigue.','Stelle dich nah an das Seil, greife auf Brusthöhe und lasse die Füße fest am Boden.','Stand close to the rope, grip at chest height and keep feet planted.','Ziehe das Seil leicht zu dir und halte nur so stark, dass Handgelenke und Schultern ruhig bleiben.','Pull rope lightly toward you and hold only as firmly as needed to keep wrists and shoulders steady.','Löse die Spannung, öffne die Hände und gehe vom Seil zurück.','Release tension, open hands and step away from the rope.','Kurze Haltezeit am Seil im Sitzen oder Handtuchgriff im Stand.','Use a short seated rope hold or standing towel grip.'),
('rope-pull-seated',2.0,'Seil und Anker prüfen; sitzende Position auf rutschfester Matte, freie Seilbahn ohne Schlaufen am Hals/Fuß.','Inspect rope and anchor; sit on non-slip mat with a clear rope path and no loops near neck or feet.','Kann aufrecht sitzen und Last kontrolliert nachlassen.','Can sit upright and release load under control.','Setze dich mit leicht gebeugten Knien hin, greife das Seil und spanne es ohne Ruck.','Sit with knees slightly bent, grip rope and take up slack without jerking.','Ziehe Hand über Hand zum Körper, halte Brust aufrecht und gib das Seil kontrolliert zurück.','Pull hand over hand toward the body, stay upright and feed rope back under control.','Lege das Seil spannungsfrei ab und stehe erst danach auf.','Lay rope down slack before standing.','Leichter Bandzug im Sitzen oder Zug mit kürzerer Seilstrecke.','Use a light seated band row or a shorter rope pull.'),
('rope-climb-footlock',4.0,'Niedrig eingestelltes Kletterseil, geprüfter Anker, Fallschutz und direkte qualifizierte Stationsaufsicht.','Use a low climbing rope with inspected anchor, fall protection and direct qualified station supervision.','Beherrscht sitzenden Seilzug und Fußklemmtechnik bodennah; kennt Stoppsignal.','Has mastered seated rope pull and low foot lock practice; knows stop signal.','Prüfe Seil und Freiraum; beginne sitzend oder stehend mit beiden Händen am Seil, ohne Anlauf.','Check rope and clear area; begin seated or standing with both hands on rope and no run-up.','Klemme das Seil mit den Füßen, stehe nur niedrig auf und führe Hände nach; Trainer kontrolliert jeden Schritt.','Clamp rope with feet, rise only a short distance and move hands up; coach checks every step.','Steige dieselbe kurze Strecke kontrolliert ab; springe nicht und lasse das Seil nicht los.','Descend the same short distance under control; do not jump or release rope.','Bodennahes Fußklemm-Üben im Sitzen plus sitzender Seilzug.','Practise foot lock at floor level while seated plus seated rope pull.'),
('scapular-swing',2.0,'Niedrige Stange, rutschfeste Landefläche und genügend Freiraum für kleine Bewegungen.','Use a low bar, non-slip landing and enough clearance for small movements.','Kann aktiven Hang halten und Spannung vor Kontrollverlust lösen.','Can hold an active hang and release before losing control.','Greife stabil, beginne im aktiven Hang und halte die Bewegung zunächst sehr klein.','Take a secure grip, begin in an active hang and keep movement very small initially.','Bewege den Brustkorb wenige Zentimeter vor und zurück aus den Schultern; kein kräftiges Kipping.','Move chest a few centimetres forward and back through shoulders; avoid forceful kipping.','Stoppe die Bewegung, setze Füße auf und löse den Griff kontrolliert.','Stop movement, place feet down and release grip under control.','Aktive Schulterblattbewegung mit Füßen gestützt im Stand.','Practise active scapular movement standing with feet supported.'),
('rig-transition',3.0,'Niedriges geprüftes Rig, Matte und markierte Warteposition; Trainer beaufsichtigt Griffwechsel einzeln.','Use a low inspected rig, mat and marked waiting spot; coach supervises individual grip changes.','Beherrscht stabilen Hang und kann Füße zum Entlasten sicher aufsetzen.','Has mastered a stable hang and can place feet down to unload safely.','Beginne an einem niedrigen Griff mit Füßen nah am Boden und prüfe den nächsten Griff.','Start from a low hold with feet near the floor and check the next hold.','Belaste den Zielgriff zuerst mit einer Hand; wechsle erst nach sicherem Halt die zweite Hand.','Load the target hold with one hand first; move the second hand only after the first is secure.','Setze Füße ab, prüfe den Griff und verlasse die Matte nach Freigabe.','Place feet down, check the hold and leave the mat when cleared.','Griffwechsel an zwei bodennahen Griffen mit dauerhaftem Fußkontakt.','Practise transfers between two low holds with continuous foot contact.'),
('assisted-rig-traverse',3.0,'Niedrige Traverse, stabile Fußstütze oder Trainerhilfe und Matte; Anker vor Nutzung prüfen.','Use a low traverse with stable foot support or coach assistance and mat; inspect anchors first.','Kann sicher greifen und auf Zuruf sofort pausieren oder absteigen.','Can grip safely and pause or dismount immediately on cue.','Greife den ersten Halt mit Füßen auf der Unterstützung; Trainer erklärt Route und Hilfestellung.','Take the first hold with feet on support; coach explains route and spotting.','Bewege dich seitlich, halte Füße unterstützt und löse immer nur einen Griffpunkt zugleich.','Move sideways with feet supported and release only one grip point at a time.','Stoppe am Endmarker, steige über die Unterstützung ab und gehe aus dem Bereich.','Stop at the end marker, dismount using support and leave the area.','Bodennahes seitliches Umgreifen an festen Griffen.','Practise low lateral hand transfers on fixed holds.')
) AS v(seed_key,clear_zone_metres,setup_de,setup_en,prereq_de,prereq_en,approach_de,approach_en,execution_de,execution_en,exit_de,exit_en,fallback_de,fallback_en);

INSERT INTO exercise_obstacle_guidance
SELECT e.id,l.locale,
  CASE l.locale WHEN 'de' THEN v.setup_de ELSE v.setup_en END,
  CASE l.locale WHEN 'de' THEN v.prereq_de ELSE v.prereq_en END,
  CASE l.locale WHEN 'de' THEN v.approach_de ELSE v.approach_en END,
  CASE l.locale WHEN 'de' THEN v.execution_de ELSE v.execution_en END,
  CASE l.locale WHEN 'de' THEN v.exit_de ELSE v.exit_en END,
  CASE l.locale WHEN 'de' THEN v.fallback_de ELSE v.fallback_en END,
  1,v.clear_zone_metres
FROM grip_rig_seed_guidance v
JOIN exercises e ON e.seed_key=v.seed_key
CROSS JOIN (VALUES ('de'),('en')) l(locale);

UPDATE exercise_details d SET
  setup=g.equipment_configuration,
  prerequisites=g.prerequisites,
  fallback_exercise=g.fallback_exercise,
  start_position=g.approach,
  finish_reset=g.exit_reset,
  quality_criteria=g.execution || ' ' || g.exit_reset,
  safety_notes=CASE WHEN e.risk_level='high'
    THEN CASE d.locale WHEN 'de' THEN 'Direkte Stationsaufsicht ist erforderlich. Anker, Griffpunkte und Fallschutz vor jedem Durchgang prüfen; nur eine Person auf der Station. Absteigen statt abspringen und bei Griffverlust, Schmerzen oder beschädigtem Gerät sofort stoppen.' ELSE 'Direct station supervision is required. Check anchors, holds and fall protection before each turn; allow one person on the station. Dismount instead of jumping and stop for grip failure, pain or damaged equipment.' END
    ELSE CASE d.locale WHEN 'de' THEN 'Trainer prüft Gerät und Landefläche, lässt nacheinander starten und erinnert daran, vor Ermüdung kontrolliert abzusteigen.' ELSE 'Coach checks equipment and landing area, sends athletes one at a time and reminds them to dismount under control before fatigue.' END END,
  supervision=CASE WHEN e.risk_level='high' THEN 'direct' ELSE 'increased' END,
  station_capacity=g.station_capacity
FROM exercise_obstacle_guidance g
JOIN exercises e ON e.id=g.exercise_id
WHERE d.exercise_id=e.id AND d.locale=g.locale;

DELETE FROM exercise_execution_steps s USING exercise_obstacle_guidance g WHERE s.exercise_id=g.exercise_id AND s.locale=g.locale;
INSERT INTO exercise_execution_steps
SELECT g.exercise_id,g.locale,n.step_order,
  CASE n.step_order WHEN 1 THEN g.approach WHEN 2 THEN g.execution ELSE g.exit_reset END
FROM exercise_obstacle_guidance g CROSS JOIN (VALUES (1),(2),(3)) n(step_order);

UPDATE exercise_common_mistakes m SET
  mistake=CASE m.locale WHEN 'de' THEN 'Der Teilnehmende greift weiter oder wechselt den Griff, obwohl die aktuelle Position nicht stabil ist.' ELSE 'The participant reaches or changes grip before the current position is stable.' END,
  correction=CASE m.locale WHEN 'de' THEN 'Bewegung anhalten, Füße zum Entlasten aufsetzen und erst nach sicherem Griff kontrolliert fortsetzen.' ELSE 'Pause, place feet down to unload and continue only after a secure grip is established.' END
FROM exercise_obstacle_guidance g
WHERE m.exercise_id=g.exercise_id AND m.locale=g.locale AND m.mistake_order=1;

DROP TABLE grip_rig_seed_guidance;

-- Source migration: 008_carry_lift_seed_guidance.sql
CREATE TABLE IF NOT EXISTS exercise_carry_guidance (
  exercise_id UUID NOT NULL REFERENCES exercises(id),
  locale VARCHAR NOT NULL CHECK (locale IN ('de','en')),
  task_kind VARCHAR NOT NULL CHECK (task_kind IN ('carry','drag','flip','team-carry')),
  intensity_rpe_min SMALLINT NOT NULL CHECK (intensity_rpe_min BETWEEN 1 AND 10),
  intensity_rpe_max SMALLINT NOT NULL CHECK (intensity_rpe_max BETWEEN intensity_rpe_min AND 10),
  load_guidance VARCHAR NOT NULL,
  route_setup VARCHAR NOT NULL,
  lifting_setup VARCHAR NOT NULL,
  movement_cue VARCHAR NOT NULL,
  turning_cue VARCHAR NOT NULL,
  finish_reset VARCHAR NOT NULL,
  fallback_exercise VARCHAR NOT NULL,
  station_capacity SMALLINT NOT NULL CHECK (station_capacity > 0),
  route_length_metres SMALLINT NOT NULL CHECK (route_length_metres > 0),
  PRIMARY KEY (exercise_id, locale)
);

CREATE TEMP TABLE carry_seed_guidance AS SELECT * FROM (VALUES
('farmer-carry','carry',3,6,1,1,'Wähle zwei gleich schwere Lasten, die du aufrecht ohne Griffverlust tragen kannst.','Choose two equal loads you can carry upright without losing grip.','Markiere eine 10–20-m-Bahn mit breiter Wendefläche und freiem Rückweg.','Mark a 10–20 m lane with a wide turn and clear return route.','Hebe beide Lasten aus Hüfte und Knien an; Rücken lang, Lasten seitlich am Körper.','Lift both loads using hips and knees; keep back long and loads beside you.','Gehe mit kurzen gleichmäßigen Schritten; wende in weitem Bogen, ohne die Lasten zu schwingen.','Walk with short even steps; turn in a wide arc without swinging the loads.','Stelle beide Lasten einzeln und kontrolliert am markierten Ende ab.','Set each load down under control at the marked end.','Kürzere Strecke oder leichtere Gegenstände; ohne Gewicht zügig marschieren.','Shorten the route or use lighter objects; brisk march without load.'),
('suitcase-carry','carry',3,6,1,1,'Nutze eine einzelne Last, bei der du aufrecht bleiben kannst, ohne zur Lastseite zu kippen.','Use one load that lets you stay upright without leaning toward it.','Markiere eine freie 10–15-m-Bahn; plane den Richtungswechsel ohne enge Drehung.','Mark a clear 10–15 m lane; plan a direction change without a tight pivot.','Hebe die Last neben einer Hüfte auf; freie Hand bleibt locker, Rippen über dem Becken.','Lift the load beside one hip; keep free hand relaxed and ribs stacked over pelvis.','Gehe geradeaus mit ruhigem Oberkörper; wechsle die Hand erst nach sicherem Absetzen.','Walk straight with a quiet torso; switch hands only after setting the load down safely.','Setze die Last am Ende kontrolliert ab und richte dich auf, bevor du die Hand wechselst.','Set the load down at the end and stand tall before switching hands.','Leichtere Last oder Marschieren ohne Gewicht mit ruhigem Oberkörper.','Use a lighter load or march without weight while keeping the torso steady.'),
('sandbag-bearhug-carry','carry',3,6,1,1,'Wähle einen Sandbag, den du nah am Rumpf halten und sicher aufnehmen kannst.','Choose a sandbag you can hold close to the torso and lift safely.','Lege den Sack auf rutschfesten Boden; markiere kurze Bahn und ausreichend breite Wendefläche.','Place bag on non-slip ground; mark a short lane and wide turn area.','Gehe in die Hüfte, umfasse den Sack eng und richte dich mit Last nah am Brustkorb auf.','Hinge at hips, hug the bag close and stand with load near the chest.','Gehe kontrolliert; wende mit kleinen Schritten und halte den Sack nah am Körper.','Walk under control; turn with small steps and keep the bag close.','Gehe in die Hüfte und setze den Sack mit beiden Armen kontrolliert ab, nicht fallen lassen.','Hinge and lower the bag with both arms; do not drop it.','Leichterer Sack oder enger Bear-Hug-Halt im Stand ohne Wegstrecke.','Use a lighter bag or practise a stationary bear-hug hold.'),
('sandbag-shoulder-carry','carry',3,6,1,1,'Nutze einen leichten Sack, der ohne ruckartiges Reißen auf eine Schulter gehoben werden kann.','Use a light bag that can be placed on one shoulder without jerking.','Markiere eine kurze freie Route; beachte Sicht und ausgeglichene Seitenwechsel.','Mark a short clear route; maintain visibility and alternate sides.','Hebe den Sack nah am Körper an und bringe ihn mit beiden Armen kontrolliert auf die Schulter.','Lift bag close to the body and place it on the shoulder with both arms under control.','Gehe mit aufrechtem Rumpf; halte den Kopf frei und wechsle die Seite nur nach Absetzen.','Walk with upright torso; keep head clear and switch sides only after setting down.','Stütze den Sack mit beiden Händen und senke ihn kontrolliert auf den Boden.','Support the bag with both hands and lower it to the floor under control.','Bear-Hug-Carry mit leichterem Sack oder kurze Halteposition beidseitig.','Use a lighter bear-hug carry or short holds on both sides.'),
('sandbag-front-carry','carry',3,6,1,1,'Belade leicht genug, dass du frei atmen und die Sicht vor dir behalten kannst.','Use a light enough load to breathe freely and see ahead.','Lege den Sack auf sicheren Boden; halte den Weg eben, kurz und frei von Gegenverkehr.','Place bag on safe ground; keep route level, short and free of opposing traffic.','Hebe den Sack körpernah und halte ihn vor dem Rumpf, ohne den Nacken einzuklemmen.','Lift bag close and hold it in front without compressing the neck.','Gehe ruhig mit kurzen Schritten; atme weiter und drehe den ganzen Körper in weitem Bogen.','Walk steadily with short steps; keep breathing and turn the whole body in a wide arc.','Setze den Sack über Hüfte und Knie kontrolliert ab und prüfe die Atmung.','Lower the bag using hips and knees and check breathing.','Leichtere Last oder Farmer-March ohne Last.','Use a lighter load or march without a load.'),
('bucket-carry','carry',3,6,1,1,'Fülle Eimer nur so, dass Griff und Inhalt sicher bleiben; vermeide schwappendes Übergewicht.','Fill buckets only so handles and contents stay secure; avoid unstable sloshing loads.','Prüfe Henkel und Boden, markiere eine kurze ebene Route und halte sie trocken.','Check handles and floor, mark a short level route and keep it dry.','Hebe den Eimer mit neutralem Rücken am Henkel an; halte ihn nahe am Bein.','Lift bucket by handle with neutral back; keep it close to the leg.','Gehe langsam genug, damit der Inhalt kontrolliert bleibt; wende weit und ohne Ruck.','Walk slowly enough to control contents; turn wide without jerking.','Stelle den Eimer aufrecht ab und lasse den Henkel erst nach sicherem Stand los.','Set the bucket upright and release handle only once stable.','Leerer oder leichter Eimer auf kürzerer Strecke.','Use an empty or lighter bucket over a shorter route.'),
('atlas-ball-carry','carry',3,6,1,1,'Verwende eine aufnehmbare Ballmasse; nur aus erhöhter Ablage oder nach geprüfter Bodenhebe-Technik starten.','Choose a manageable ball; start from a raised surface or after checking floor-lift technique.','Direkte Aufsicht, griffige ebene Bahn und breite Wendefläche; keine Laufspur kreuzen.','Provide direct supervision, grippy level lane and wide turn; do not cross running routes.','Umfasse den Ball tief, spanne den Rumpf an und hebe ihn eng am Körper mit Beinen und Hüfte.','Wrap arms low around the ball, brace and lift close using legs and hips.','Trage langsam und halte Sicht frei; wende in mehreren kleinen Schritten statt auf einem Fuß.','Carry slowly with clear vision; turn in several small steps, not on a planted foot.','Senke den Ball über Hüfte und Knie auf eine freie Matte; nicht aus Schulterhöhe fallen lassen.','Lower ball through hips and knees onto a clear mat; do not drop from shoulder height.','Erhöhte leichtere Medizinball-Aufnahme oder Bear-Hug mit kleinem Ball.','Use a raised lighter medicine-ball pick-up or a small ball bear hug.'),
('team-object-carry','team-carry',2,5,2,2,'Wähle einen gemeinsamen Gegenstand, den alle Beteiligten stabil halten können; keine Person darf das Gewicht allein auffangen.','Choose a shared object everyone can hold steadily; no one should have to catch the load alone.','Markiere eine kurze freie Route; Team bestimmt vorab Start, Halt, Wendung und Absetzen.','Mark a short clear route; team agrees start, stop, turn and set-down commands first.','Stellt euch gleichmäßig um den Gegenstand, greift sichere Stellen und hebt gemeinsam auf ein klares Signal.','Space evenly around object, use secure holds and lift together on a clear signal.','Eine Person gibt Tempo und Wendung an; alle gehen in kleinen Schritten und melden Griffprobleme sofort.','One person calls pace and turns; everyone takes small steps and reports grip problems immediately.','Auf gemeinsames Signal gemeinsam absetzen; niemand lässt ein Ende plötzlich los.','Set down together on a shared cue; nobody releases one end suddenly.','Leichterer oder kleinerer Gegenstand; synchrones Gehen ohne Last üben.','Use a lighter or smaller object; practise synchronised walking without load.'),
('sled-drag','drag',3,6,1,1,'Stelle den Schlitten so leicht ein, dass du gleichmäßig ziehen kannst, ohne ruckartig rückwärts zu stolpern.','Load sled so you can pull steadily without jerking or stumbling backward.','Prüfe Zugleine und Schlitten; markiere gerade Bahn, freie Endzone und Wendepunkt.','Check rope and sled; mark a straight lane, clear end zone and turn point.','Greife die Leine sicher, richte dich zur Zugrichtung aus und spanne sie vor dem ersten Schritt.','Grip rope securely, face direction of travel and take slack out before stepping.','Gehe rückwärts oder vorwärts wie demonstriert; halte Zug konstant und blicke regelmäßig in Laufrichtung.','Walk backward or forward as demonstrated; keep pull steady and check travel path.','Löse Spannung kontrolliert, sichere die Leine und gehe um den Schlitten zurück.','Release tension gradually, secure rope and walk back around the sled.','Leichterer Schlitten oder isometrischer Seilzug mit stabiler Verankerung.','Use a lighter sled or isometric rope pull from a stable anchor.'),
('tire-drag','drag',3,6,1,1,'Nutze einen intakten Reifen mit sicherer Zugverbindung und Belastung, die gleichmäßiges Ziehen erlaubt.','Use an intact tire with secure tether and a load that allows steady pulling.','Prüfe Befestigung, Untergrund und Zugbahn; halte Zuschauer außerhalb der Zugrichtung.','Check attachment, surface and lane; keep bystanders outside the pulling line.','Stelle dich stabil vor die Leine, greife beidseitig und spanne ohne Ruck an.','Stand firmly in front of rope, grip with both hands and take tension without jerking.','Ziehe mit kurzen gleichmäßigen Schritten aus Beinen und Hüfte; halte Hände und Leine weg vom Gesicht.','Pull with short even steps using legs and hips; keep hands and rope away from face.','Stoppe vollständig, lege die Leine spannungsfrei ab und gehe außen zurück.','Come to a full stop, release rope tension and return around the lane.','Leichter leerer Reifen oder Bandzug im Stand.','Use a lighter empty tire or standing band pull.'),
('tire-flip','flip',3,6,1,1,'Nur kleiner stabiler Reifen; Trainer demonstriert. Last erlaubt kontrolliertes Kippen ohne Springen oder Rundrücken.','Use only a small stable tire; coach demonstrates. Load must allow a controlled tip without jumping or rounding back.','Ebener griffiger Boden, freie Rollrichtung und direkte Aufsicht; niemand steht vor oder hinter dem Reifen.','Use level grippy ground, clear roll path and direct supervision; nobody stands in front or behind tire.','Gehe nah heran, Füße stabil; greife unter die Reifenkante und spanne den Rumpf an.','Stand close with stable feet; grip beneath tire edge and brace trunk.','Drücke aus Beinen und Hüfte nach vorn-oben; Hände wechseln erst, wenn der Reifen stabil kippt.','Drive forward and up through legs and hips; reposition hands only once tire tips steadily.','Weiche seitlich aus, begleite den Reifen bis zum sicheren Liegen und richte dich neu auf.','Step to the side, guide tire to a stable rest and reset posture.','Erhöhten leichten Sandsack vom Boden auf eine Ablage heben, ohne Wurf.','Lift a light elevated sandbag from floor to a platform without throwing.')
) AS v(seed_key,task_kind,rpe_min,rpe_max,station_capacity,route_length_metres,load_de,load_en,route_de,route_en,movement_de,movement_en,turn_de,turn_en,finish_de,finish_en,fallback_de,fallback_en);

INSERT INTO exercise_carry_guidance
SELECT e.id,l.locale,v.task_kind,v.rpe_min,v.rpe_max,
  CASE l.locale WHEN 'de' THEN v.load_de ELSE v.load_en END,
  CASE l.locale WHEN 'de' THEN v.route_de ELSE v.route_en END,
  CASE l.locale WHEN 'de' THEN 'Stelle dich dicht an die Last, spanne den Rumpf an und hebe aus Hüfte und Knien.' ELSE 'Stand close to the load, brace your trunk and lift through hips and knees.' END,
  CASE l.locale WHEN 'de' THEN v.movement_de ELSE v.movement_en END,
  CASE l.locale WHEN 'de' THEN v.turn_de ELSE v.turn_en END,
  CASE l.locale WHEN 'de' THEN v.finish_de ELSE v.finish_en END,
  CASE l.locale WHEN 'de' THEN v.fallback_de ELSE v.fallback_en END,
  v.station_capacity,v.route_length_metres
FROM carry_seed_guidance v
JOIN exercises e ON e.seed_key=v.seed_key
CROSS JOIN (VALUES ('de'),('en')) l(locale);

UPDATE exercise_details d SET
  purpose=CASE d.locale WHEN 'de' THEN t.name || ': ' || g.load_guidance ELSE t.name || ': ' || g.load_guidance END,
  setup=g.route_setup || ' ' || g.lifting_setup,
  start_position=g.lifting_setup,
  tempo_cue=g.load_guidance || ' RPE ' || CAST(g.intensity_rpe_min AS VARCHAR) || '–' || CAST(g.intensity_rpe_max AS VARCHAR) || '/10.',
  quality_criteria=g.movement_cue || ' ' || g.turning_cue,
  beginner_prescription=CASE d.locale WHEN 'de' THEN '2 × 10 m bei RPE ' || CAST(g.intensity_rpe_min AS VARCHAR) || '–4; Last bei sauberer Haltung steigern.' ELSE '2 × 10 m at RPE ' || CAST(g.intensity_rpe_min AS VARCHAR) || '–4; increase load only while posture stays sound.' END,
  standard_prescription=CASE d.locale WHEN 'de' THEN '3 × ' || CAST(g.route_length_metres AS VARCHAR) || ' m bei RPE ' || CAST(g.intensity_rpe_min AS VARCHAR) || '–' || CAST(g.intensity_rpe_max AS VARCHAR) || '/10.' ELSE '3 × ' || CAST(g.route_length_metres AS VARCHAR) || ' m at RPE ' || CAST(g.intensity_rpe_min AS VARCHAR) || '–' || CAST(g.intensity_rpe_max AS VARCHAR) || '/10.' END,
  advanced_prescription=CASE d.locale WHEN 'de' THEN 'Bis 4 Durchgänge; erst Strecke oder Last einzeln erhöhen, nicht beides zusammen.' ELSE 'Build to 4 rounds; increase distance or load separately, not both together.' END,
  work_rest_guidance=CASE d.locale WHEN 'de' THEN 'Zwischen Durchgängen 60–120 Sekunden oder bis Atmung und Griff sicher kontrolliert sind.' ELSE 'Rest 60–120 seconds between rounds or until breathing and grip are controlled.' END,
  finish_reset=g.finish_reset,
  fallback_exercise=g.fallback_exercise,
  safety_notes=CASE WHEN e.risk_level='high'
    THEN CASE d.locale WHEN 'de' THEN 'Direkte Aufsicht. Last und Befestigung vor jedem Versuch prüfen, Route vollständig freihalten und Lasten nicht aus Schulterhöhe fallen lassen. Bei Schmerz, Griffverlust oder Kontrollverlust abbrechen.' ELSE 'Direct supervision. Check load and attachment before each attempt, keep the full route clear and do not drop loads from shoulder height. Stop for pain, grip failure or loss of control.' END
    ELSE CASE d.locale WHEN 'de' THEN 'Untergrund und Griff vor dem Start prüfen; Last kontrolliert aufnehmen und absetzen. Bei Schmerzen, Stolpern oder unsicherem Griff stoppen.' ELSE 'Check surface and grip before starting; lift and set down under control. Stop for pain, stumbling or insecure grip.' END END,
  station_capacity=g.station_capacity,
  supervision=CASE WHEN e.risk_level='high' THEN 'direct' ELSE 'increased' END
FROM exercise_carry_guidance g
JOIN exercises e ON e.id=g.exercise_id
JOIN exercise_translations t ON t.exercise_id=e.id
WHERE d.exercise_id=e.id AND d.locale=g.locale AND t.locale=g.locale;

DELETE FROM exercise_execution_steps s USING exercise_carry_guidance g WHERE s.exercise_id=g.exercise_id AND s.locale=g.locale;
INSERT INTO exercise_execution_steps
SELECT g.exercise_id,g.locale,n.step_order,
  CASE n.step_order WHEN 1 THEN g.route_setup || ' ' || g.lifting_setup
    WHEN 2 THEN g.movement_cue || ' ' || g.turning_cue
    ELSE g.finish_reset END
FROM exercise_carry_guidance g CROSS JOIN (VALUES (1),(2),(3)) n(step_order);

UPDATE exercise_coaching_cues c SET cue=CASE c.locale
  WHEN 'de' THEN CASE c.cue_order WHEN 1 THEN 'Last nah am Körper' WHEN 2 THEN 'Kurze ruhige Schritte' ELSE 'Kontrolliert absetzen' END
  ELSE CASE c.cue_order WHEN 1 THEN 'Keep load close' WHEN 2 THEN 'Short steady steps' ELSE 'Set down with control' END END
FROM exercise_carry_guidance g WHERE c.exercise_id=g.exercise_id AND c.locale=g.locale;

UPDATE exercise_common_mistakes m SET
  mistake=CASE m.locale WHEN 'de' THEN 'Last wird mit rundem Rücken aufgenommen, geschwungen oder unkontrolliert abgesetzt.' ELSE 'Load is lifted with a rounded back, swung or set down without control.' END,
  correction=CASE m.locale WHEN 'de' THEN 'Last näher heranholen, Hüfte und Knie beugen, leichter wählen und Aufnahme sowie Absetzen erneut vormachen.' ELSE 'Bring the load closer, bend hips and knees, reduce the load and demonstrate the lift and set-down again.' END
FROM exercise_carry_guidance g WHERE m.exercise_id=g.exercise_id AND m.locale=g.locale AND m.mistake_order=1;

DROP TABLE carry_seed_guidance;

-- Source migration: 009_warmup_seed_enrichment.sql
CREATE TEMP TABLE warmup_seed_enrichment AS
SELECT * FROM (VALUES
('easy-jog','de','Lockeres Einlaufen baut die Belastung schrittweise auf und macht den Laufstil vor dem Hauptteil beobachtbar.','Erhöht die Körpertemperatur ohne die Gruppe vorzeitig zu ermüden; der Trainer kann Atmung und Laufbild prüfen.','Markiere eine ebene, rutschfeste Schleife mit breiten Wendungen und freier Auslaufzone.','Gehe zunächst aufrecht los; Blick voraus, Schultern locker und Arme pendeln neben dem Körper.','Bei Stolperstelle, Atemnot, Schmerz oder zunehmender Unsicherheit sofort ins Gehen wechseln und Strecke freigeben.','Gleichmäßige leise Schritte, lockere Hände und vollständige Sätze beim Sprechen bleiben möglich.','4 Minuten zügig gehen, dann 4 Minuten sehr locker joggen.','6–8 Minuten am Stück im Gesprächstempo.','10 Minuten locker; nur die letzten 2 Minuten leicht steigern, solange die Gruppe entspannt bleibt.','Das Tempo ist absichtlich leicht; wer nicht sprechen kann, geht bis die Atmung ruhig ist.','Mit 2 Minuten Gehen und 2 Minuten lockerem Traben beginnen.','Ohne Gehpausen 8 Minuten gleichmäßig joggen.','Auf den letzten 2 Minuten die Schrittfrequenz leicht erhöhen, nicht sprinten.','Kinder laufen eine kurze markierte Runde und wählen selbst zwischen Gehen und Traben; niemand wird abgehängt.','Die Runde sicher gehend absolvieren und dabei den Weg frei halten.','Durch zügiges Gehen auf derselben Strecke ersetzen.'
),('easy-jog','en','Easy jogging raises effort gradually and lets the coach observe running form before the main work.','Raises body temperature without tiring the group; the coach can check breathing and running mechanics.','Mark a flat, non-slip loop with wide turns and a clear run-out area.','Start with an upright walk; look ahead, relax the shoulders and swing the arms beside the body.','Walk and clear the route for a trip hazard, pain, unusual breathlessness or loss of control.','Quiet even steps, relaxed hands and the ability to speak in full sentences.','Walk briskly for 4 minutes, then jog easily for 4 minutes.','Jog continuously for 6–8 minutes at conversational effort.','Jog easily for 10 minutes; slightly increase pace only for the final 2 minutes if relaxed.','Keep effort easy; anyone unable to speak comfortably walks until breathing settles.','Begin with 2 minutes walking and 2 minutes easy jogging.','Jog steadily for 8 minutes without walk breaks.','Slightly raise cadence for the final 2 minutes; do not sprint.','Children use a short marked loop and choose between walking and jogging; keep the group together without chasing.','Walk the marked route and keep the path clear.','Replace with brisk walking on the same route.'
),('walk-jog','de','Der Wechsel aus Gehen und lockerem Laufen übt einen selbst gesteuerten Einstieg in Ausdauerbelastung.','Vermittelt, Belastung und Erholung bewusst zu wechseln und ein Tempo zu finden, das über mehrere Abschnitte tragbar ist.','Lege eine ebene Wendestrecke fest und erkläre gut hörbar das Wechselzeichen; halte Gegenverkehr aus der Bahn.','Starte gehend mit aufrechtem Oberkörper und beginne den Trab erst auf das vereinbarte Signal.','Bei rutschigem Boden, stechendem Schmerz oder Schwindel aussteigen und den Trainer informieren.','Der Wechsel erfolgt ohne abrupten Sprint; im Laufabschnitt bleibt ruhige Nasen- oder Lippenatmung möglich.','6-mal 1 Minute gehen und 1 Minute traben.','8-mal 90 Sekunden traben und 60 Sekunden gehen.','6-mal 3 Minuten locker laufen und 1 Minute gehen.','Gehpausen sind geplant und kein Wettkampf; niemand muss andere einholen.','6 Wechsel mit je 30 Sekunden Gehen und Traben.','8 Wechsel mit 90 Sekunden Traben und 60 Sekunden Gehen.','10 Wechsel mit 2 Minuten Laufen und 30 Sekunden Gehen.','Signalkarten zeigen Gehen oder Traben; kurze Abschnitte und freie Wahl sorgen für Erfolgserlebnisse.','Auf der markierten Route sicher gehen und auf die Wechselzeichen reagieren können.','Statt Traben durch zügiges Gehen mit denselben Wechselzeiten ersetzen.'
),('walk-jog','en','Alternating walking and easy jogging practises self-paced entry into endurance work.','Teaches athletes to switch deliberately between effort and recovery and choose a pace they can sustain.','Set a flat out-and-back route and explain the audible change signal; keep opposing traffic out of the lane.','Begin walking upright and start jogging only at the agreed signal.','Stop and tell the coach if the surface is slippery or sharp pain or dizziness occurs.','Transitions are smooth rather than sprinting; breathing stays calm during each jogging interval.','Complete 6 rounds of 1 minute walking and 1 minute jogging.','Complete 8 rounds of 90 seconds jogging and 60 seconds walking.','Complete 6 rounds of 3 minutes easy running and 1 minute walking.','Walk breaks are planned recovery, not a race; no one needs to catch another athlete.','Complete 6 changes of 30 seconds walking and jogging.','Complete 8 rounds of 90 seconds jogging and 60 seconds walking.','Complete 10 rounds of 2 minutes running and 30 seconds walking.','Use walk or jog signal cards; keep intervals short and let children choose their pace.','Walk the marked route safely and respond to the change signal.','Replace jogging with brisk walking for the same intervals.'
),('high-knees','de','Der Kniehebelauf bereitet Hüftbeugung und Fußaufsatz für Lauf-ABC und kurze Beschleunigungen vor.','Trainiert aktiven Abdruck und Rhythmus; die Kniehöhe bleibt der Beweglichkeit und Kontrolle angepasst.','Markiere eine 10–15-Meter-Bahn mit sicherer Auslaufzone; beginne ohne Hütchen oder Hindernisse.','Stehe groß, spanne den Rumpf leicht an und halte die Arme in lockerer Laufposition.','Bei hartem Aufstampfen, Gleichgewichtsverlust oder Beschwerden Tempo reduzieren und auf normales Gehen wechseln.','Der Fuß setzt unter dem Körper auf; der Oberkörper bleibt ruhig und die Bewegung federt leise.','2 Durchgänge à 10 Meter im Marsch mit deutlicher Kniehebung.','3 Durchgänge à 15 Meter locker und rhythmisch; zurückgehen.','4 Durchgänge à 20 Meter mit etwas höherer Schrittfrequenz bei unveränderter Kontrolle.','Knie nur so hoch heben, wie Becken und Oberkörper ruhig bleiben; Geschwindigkeit ist kein Ziel.','Auf der Stelle abwechselnd das Knie bis zur angenehmen Höhe heben.','15 Meter mit aktivem Armschwung und ruhigem Oberkörper laufen.','20 Meter rhythmisch laufen und danach kontrolliert auslaufen.','Als Marschspiel über kurze Distanzen; die Kinder wählen Kniehöhe und Tempo selbst.','Auf der Stelle mit sicherem Stand abwechselnd die Knie heben.','Durch zügiges Marschieren auf ebener Fläche ersetzen.'
),('high-knees','en','High knees prepare hip drive and foot placement for running drills and short accelerations.','Practises an active push-off and rhythm; knee height stays within the athlete’s mobility and control.','Mark a 10–15 metre lane with a safe run-out; begin without cones or obstacles.','Stand tall, lightly brace the trunk and hold the arms in a relaxed running position.','Reduce pace or return to walking if steps become loud, balance is lost or discomfort appears.','Feet land beneath the body; the torso stays quiet and steps remain light.','Complete 2 x 10 metres marching with clear knee lift.','Complete 3 x 15 metres with an easy rhythm; walk back.','Complete 4 x 20 metres with a slightly quicker cadence while keeping control.','Lift only as high as the pelvis and torso stay steady; speed is not the goal.','March in place and lift each knee to a comfortable height.','Run 15 metres with active arm swing and a quiet torso.','Run rhythmically for 20 metres, then decelerate under control.','Use a short marching game; children choose a comfortable knee height and pace.','Alternate knee lifts while standing in a stable spot.','Replace with brisk marching on a flat surface.'
),('butt-kicks','de','Anfersen vermittelt einen schnellen, lockeren Beinrückholweg als Lauf-ABC-Variante.','Übt den Rhythmus der Beinrückführung, ohne dass die Ferse den Po erreichen muss.','Nutze eine ebene 10–15-Meter-Bahn mit freiem Rückweg; demonstriere zuerst langsames Lauf-ABC.','Stehe aufrecht, beuge die Arme und laufe mit kleinen, lockeren Schritten an.','Keine Ferse zum Gesäß ziehen oder Knie nach hinten drücken; bei Zuggefühl abbrechen.','Die Ferse schwingt locker nach hinten, der Fuß landet unter der Hüfte und der Kopf bleibt ruhig.','2 x 10 Meter im lockeren Marsch mit kleiner Fersenbewegung.','3 x 15 Meter als leichtes Lauf-ABC; auf dem Rückweg gehen.','4 x 20 Meter etwas flüssiger, aber nur bei unverändert leisem Fußaufsatz.','Die Ferse muss das Gesäß nicht berühren; eine kleine schmerzfreie Bewegung genügt.','Auf der Stelle abwechselnd die Ferse locker nach hinten führen.','15 Meter mit leichtem Lauf und natürlicher Fersenrückführung.','20 Meter mit flüssigem Rhythmus und anschließendem kontrolliertem Auslaufen.','Als langsames Laufspiel in kurzen Bahnen; auf kleine, leichte Schritte achten.','Im Stand abwechselnd die Fersen leicht anheben und sicher absetzen.','Durch lockeres Traben ohne betonte Fersenbewegung ersetzen.'
),('butt-kicks','en','Butt kicks practise a quick, relaxed leg recovery as a running drill.','Builds the rhythm of the recovery phase; the heel does not need to touch the glute.','Use a flat 10–15 metre lane with a clear return path; demonstrate the drill slowly first.','Stand tall, bend the arms and start with small, relaxed running steps.','Do not pull the heel to the glute or force the knee back; stop if the front of the knee feels strained.','The heel swings back loosely, the foot lands under the hip and the head remains steady.','Complete 2 x 10 metres marching with a small heel lift.','Complete 3 x 15 metres as a light running drill; walk back.','Complete 4 x 20 metres at a smoother rhythm only if steps stay quiet.','The heel need not touch the glute; a small pain-free movement is enough.','Stand in place and alternate a relaxed heel lift behind you.','Run 15 metres with a light stride and natural heel recovery.','Run 20 metres with a smooth rhythm, then decelerate under control.','Use a slow short-lane running game and cue small, light steps.','Alternate small heel lifts while standing securely.','Replace with easy jogging without an exaggerated heel lift.'
),('side-shuffle','de','Der Seitgalopp trainiert seitliche Fortbewegung und kontrolliertes Abbremsen ohne Überkreuzen der Füße.','Bereitet Hüfte und Sprunggelenk auf seitliche Richtungswechsel im Spielfeld vor.','Markiere zwei Linien im Abstand von 5–8 Metern; halte die Bahn frei und vermeide rutschigen Boden.','Stelle dich seitlich zur Laufrichtung, Füße hüftbreit, Knie weich und Blick voraus.','Überkreuze die Füße nicht; Abstand so wählen, dass niemand in die Nachbarbahn gerät.','Die Füße bleiben parallel, Schritte sind klein und die Hüfte sinkt nur leicht ab.','4 x 5 Meter je Richtung im Gehtempo.','4 x 8 Meter je Richtung mit ruhigem Seitgalopp; an der Linie stabil stoppen.','5 x 10 Meter je Richtung, nur bei sicherem Stopp etwas flüssiger.','Kleine Schritte und Platz in der eigenen Bahn haben Vorrang vor Tempo.','Seitlich 3–5 Meter gehen und an jeder Linie sicher anhalten.','8 Meter seitgaloppieren und vor der Linie kontrolliert stoppen.','10 Meter je Richtung mit klarer Beschleunigung und sauberem Stopp.','Linien-Spiel in Paaren: seitlich zur Linie und auf ein Signal stehen bleiben; ohne Ausscheidung.','Zwischen nahen Linien seitlich gehen und auf das Stoppsignal reagieren.','Durch seitliches Gehen auf kürzerer Strecke ersetzen.'
),('side-shuffle','en','The side shuffle trains lateral travel and controlled braking without crossing the feet.','Prepares hips and ankles for lateral changes of direction in field sports.','Mark two lines 5–8 metres apart; keep the lane clear and avoid slippery ground.','Face sideways to the lane with feet hip-width apart, soft knees and eyes forward.','Do not cross the feet; use separate lanes so athletes cannot collide.','Feet stay parallel, steps stay short and the hips lower only slightly.','Complete 4 x 5 metres in each direction at walking pace.','Complete 4 x 8 metres each way and stop steadily at the line.','Complete 5 x 10 metres each way; increase flow only if every stop is controlled.','Short steps and space in the lane matter more than speed.','Side-step 3–5 metres between close lines and stop safely.','Shuffle 8 metres and brake under control before the line.','Cover 10 metres each way with a clear acceleration and controlled stop.','Use a paired line game: shuffle to the line and freeze on a signal; no elimination.','Side-walk between nearby lines and respond to the stop signal.','Replace with slower lateral walking over a shorter distance.'
),('carioca','de','Carioca verbindet seitliche Fortbewegung mit einer kontrollierten Überkreuzkoordination.','Schult Hüftrotation und Schrittkoordination in moderatem Tempo als Vorbereitung auf Richtungswechsel.','Richte eine ebene 8–10-Meter-Bahn mit viel Abstand zwischen den Personen ein; zeige die Schrittfolge im Stand.','Stehe seitlich zur Bahn, Knie leicht gebeugt und Arme locker zur Balance geöffnet.','Nur so weit überkreuzen, dass das Standbein stabil bleibt; bei Stolpern sofort anhalten.','Der Oberkörper bleibt weitgehend nach vorn gerichtet und die Schritte bleiben leicht und rhythmisch.','2 x 8 Meter langsam mit Gehschrittfolge, beide Richtungen.','3 x 10 Meter locker; beim Richtungswechsel neu sortieren statt herumzudrehen.','4 x 10 Meter mit flüssigem Rhythmus, nicht mit maximaler Geschwindigkeit.','Die Kreuzschritte klein halten; zuerst Schrittfolge, danach erst Rhythmus.','Schrittfolge im Stand üben: vor dem Standbein kreuzen und seitlich öffnen.','8 Meter pro Richtung mit sicherer Schrittfolge gehen.','10 Meter pro Richtung flüssig laufen und am Ende kontrolliert stoppen.','Schrittfolge als langsames Spiegelspiel; Kinder bleiben in markierten Einzelbahnen.','Im Stand einen Fuß vor dem anderen kreuzen und wieder öffnen.','Durch Seitgalopp ohne Überkreuzen ersetzen.'
),('carioca','en','Carioca combines lateral travel with controlled crossing-step coordination.','Develops hip rotation and footwork at moderate pace as preparation for direction changes.','Set a flat 8–10 metre lane with generous spacing; teach the foot pattern while stationary.','Face sideways to the lane with soft knees and arms relaxed for balance.','Cross only as far as the stance leg remains stable; stop immediately after a stumble.','Keep the torso mostly facing forward and steps light and rhythmic.','Complete 2 x 8 metres slowly using the walking pattern in both directions.','Complete 3 x 10 metres easily; reset the pattern before changing direction.','Complete 4 x 10 metres with a fluent rhythm, never at maximum speed.','Keep crossing steps small; learn the pattern before increasing rhythm.','Practise in place: cross in front of the stance leg, then step sideways open.','Walk 8 metres in each direction with a secure pattern.','Travel 10 metres each way smoothly and stop under control.','Use a slow mirror-footwork game in marked individual lanes.','Cross one foot in front while standing, then return to the open stance.','Replace with a side shuffle without crossing the feet.'
),('arm-circles','de','Armkreisen bewegt das Schultergelenk kontrolliert durch einen schmerzfreien Bewegungsbogen.','Bereitet Schultern und oberen Rücken auf Stütz-, Wurf- oder Zugbewegungen vor; die Größe wächst nur mit guter Kontrolle.','Stelle die Gruppe mit Armlänge Abstand auf; kein Material nötig.','Stehe stabil, Knie locker, Rippen über dem Becken und Arme seitlich auf Schulterhöhe.','Bei stechendem Schmerz oder Taubheitsgefühl sofort stoppen und den Kreis kleiner machen.','Rumpf und Rippen bleiben ruhig; beide Arme bewegen sich gleichmäßig ohne Schwung.','Je 8 kleine Kreise vorwärts und rückwärts.','Je 10 mittlere Kreise vorwärts und rückwärts, entspannt atmen.','Je 12 kontrollierte Kreise; den Bewegungsbogen nur bei Wohlgefühl vergrößern.','Kreisgröße schmerzfrei wählen und Schulterhochziehen vermeiden.','Arme unter Schulterhöhe halten und je 6 kleine Kreise ausführen.','Je 10 Kreise auf Schulterhöhe in beide Richtungen.','Je 12 größere kontrollierte Kreise ohne Rumpfbewegung.','Als gemeinsames Spiegeln kleiner und großer Kreise; jedes Kind bleibt im eigenen Abstand.','Arme locker hängen lassen und kleine Kreise nur im angenehmen Bereich machen.','Durch Schulterblatt-Zusammenziehen und -Lösen mit Armen am Körper ersetzen.'
),('arm-circles','en','Arm circles move the shoulder joint through a controlled, pain-free range.','Prepare the shoulders and upper back for support, throwing or pulling; enlarge the circle only while control remains.','Space athletes an arm’s length apart; no equipment is needed.','Stand steadily with soft knees, ribs stacked over pelvis and arms at shoulder height.','Stop for sharp pain or numbness and reduce the circle size if movement feels uncomfortable.','Keep the trunk and ribs still; both arms move evenly without momentum.','Complete 8 small circles forward and backward.','Complete 10 medium circles in each direction while breathing easily.','Complete 12 controlled circles; enlarge the range only if comfortable.','Choose a pain-free circle and avoid shrugging the shoulders.','Keep arms below shoulder height and make 6 small circles each way.','Complete 10 circles at shoulder height in both directions.','Complete 12 larger controlled circles without moving the trunk.','Mirror small and large circles together while each child keeps personal space.','Let arms hang and make small circles only in a comfortable range.','Replace with shoulder-blade squeezes and releases with arms by the sides.'
),('inchworm','de','Der Inchworm verbindet eine kurze Rumpfstützphase mit kontrolliertem Vorbeugen und Schulterbewegung.','Erwärmt Schultern, Rumpf und hintere Beinlinie; die Hände wandern nur so weit, wie der Rücken stabil bleibt.','Nutze rutschfeste Matten oder einen sauberen Boden und lasse mindestens zwei Armlängen Abstand.','Stehe hüftbreit und beuge die Knie so weit, dass die Hände den Boden sicher erreichen.','Bei Handgelenksschmerz auf Fäuste oder erhöhte Hände wechseln; nicht in eine schmerzhafte Dehnung drücken.','Beim Wandern bleiben die Schritte klein; in der Stützposition bilden Kopf, Rumpf und Becken eine Linie.','4 Wiederholungen mit gebeugten Knien und kurzer Stützzeit.','6 langsame Wiederholungen; Hände vorlaufen und Füße in kleinen Schritten nachführen.','8 Wiederholungen mit stabiler Stützposition und etwas längerer Reichweite.','Die Knie dürfen gebeugt bleiben; Reichweite endet bevor der untere Rücken durchhängt.','Hände auf eine Bank setzen und 4 kurze Vor- und Rückwege machen.','6 Wiederholungen am Boden mit gebeugten Knien.','8 Wiederholungen mit gestreckteren Beinen, sofern der Rücken stabil bleibt.','Als Raupen-Weg über kurze Distanz; langsames Tempo und freie Matte für jedes Kind.','Hände auf eine erhöhte Fläche setzen und nur wenige Schritte vorlaufen.','Durch erhöhten Wandstütz mit abwechselndem Schultertippen ersetzen.'
),('inchworm','en','The inchworm links a short bracing position with a controlled forward fold and shoulder movement.','Warms shoulders, trunk and hamstrings; walk the hands only as far as the back stays steady.','Use non-slip mats or a clean floor and leave at least two arm-lengths between athletes.','Stand hip-width apart and bend the knees enough for the hands to reach the floor safely.','Use fists or raise the hands for wrist discomfort; never force a painful stretch.','Take small hand steps; in the plank, head, trunk and pelvis stay aligned.','Complete 4 repetitions with bent knees and a brief plank.','Complete 6 slow repetitions, walking the hands out and feet forward in small steps.','Complete 8 repetitions with a stable plank and slightly longer reach.','Knees may stay bent; stop before the lower back sags.','Place hands on a bench and complete 4 short out-and-back walks.','Complete 6 floor repetitions with bent knees.','Complete 8 repetitions with straighter legs only while the back remains steady.','Use a short caterpillar walk on a clear mat; keep it slow and give each child room.','Raise hands on a stable surface and take only a few steps out.','Replace with an elevated wall plank and alternating shoulder taps.'
),('jumping-jacks','de','Hampelmänner koordinieren Arm- und Beinöffnung mit einem federnden, rhythmischen Sprung.','Erhöhen Puls und Ganzkörpertemperatur; die Landung wird weich gehalten und kann bei Bedarf ohne Sprung erfolgen.','Prüfe rutschfesten Boden und ausreichenden Seitenabstand; entferne Taschen und lose Hütchen.','Stehe aufrecht mit Füßen zusammen, Armen seitlich und Blick nach vorn.','Bei Gelenkschmerz, lauter harter Landung oder fehlendem Platz auf die Schrittvariante wechseln.','Leise auf dem Vorfuß-Mittelfußbereich landen, Knie folgen den Zehen und Arme bewegen sich ohne Schulterzwang.','2 x 20 Sekunden Step-Jacks ohne Sprung, dazwischen 20 Sekunden Pause.','3 x 20 Sekunden Hampelmänner mit 30 Sekunden Pause.','4 x 30 Sekunden im gleichmäßigen Rhythmus; nur solange Landungen leise bleiben.','Ohne Sprung ausführen, wenn die Landung nicht leise und stabil gelingt.','Step-Jack: einen Fuß seitlich setzen und Arme bis Schulterhöhe heben.','20 Sekunden rhythmische Hampelmänner, danach 30 Sekunden locker gehen.','30 Sekunden gleichmäßige Wiederholungen mit weicher Landung.','Musik-Stopp-Spiel mit Step-Jacks oder kleinen Sprüngen; Kinder wählen selbst die Variante.','Seitliches Tippen ohne Sprung und Arme nur bis zur angenehmen Höhe heben.','Durch zügiges Marschieren mit abwechselndem Armheben ersetzen.'
),('jumping-jacks','en','Jumping jacks coordinate opening the arms and legs with a light rhythmic jump.','Raises pulse and whole-body temperature; land softly and switch to a no-jump option when needed.','Check non-slip flooring and generous side spacing; move bags and loose cones away.','Stand tall with feet together, arms by the sides and eyes forward.','Switch to the step version for joint discomfort, loud hard landings or limited space.','Land quietly through the mid-foot, let knees track over toes and move arms without forcing the shoulders.','Complete 2 x 20 seconds of step jacks without jumping, resting 20 seconds.','Complete 3 x 20 seconds of jumping jacks with 30 seconds rest.','Complete 4 x 30 seconds at an even rhythm only while landings stay quiet.','Remove the jump whenever a quiet, stable landing is not consistent.','Step one foot sideways and lift arms to shoulder height, alternating sides.','Perform rhythmic jumping jacks for 20 seconds, then walk easily for 30 seconds.','Complete 30 seconds of even repetitions with soft landings.','Play a music-stop game using step jacks or small jumps; children choose their version.','Tap one foot sideways without jumping and lift arms only to a comfortable height.','Replace with brisk marching and alternating arm lifts.'
),('reaction-tag','de','Das Reaktions-Fangspiel trainiert Wahrnehmung, Antritt und Richtungswechsel in einem klar begrenzten Feld.','Verknüpft ein eindeutiges Signal mit kontrollierter Beschleunigung und Abbremsung; Fangdruck und Körperkontakt bleiben ausgeschlossen.','Markiere ein kleines rechteckiges Feld mit flachen Hütchen und erkläre Stopp, Aus und sichere Auslaufwege.','Verteile die Gruppe mit genügend Abstand; starte im Gehen und höre auf das vereinbarte Farb- oder Rufsignal.','Kein Schubsen, Greifen oder Blockieren; bei Sturz sofort Spiel stoppen und Feld freimachen.','Richtungswechsel erfolgen mit kurzen Schritten und kontrolliertem Bremsen; niemand läuft blind rückwärts.','4 x 20 Sekunden mit Gehen und einfachem Signal, je 40 Sekunden Pause.','5 x 30 Sekunden bei lockerem Tempo mit 30–45 Sekunden Pause.','6 x 30 Sekunden; nur eine Regel oder ein Signal gleichzeitig schwieriger machen.','Das Feld verkleinern statt Tempo zu erzwingen; Stoppsignal gilt jederzeit.','In Paaren auf ein Signal zur passenden Linie gehen statt laufen.','20 Sekunden locker reagieren und auf das Stoppzeichen sicher stehen.','30 Sekunden mit zwei bekannten Signalen und kontrolliertem Richtungswechsel.','Kooperative Farb-Suche: alle laufen zu einer Farbe; niemand scheidet aus oder wird berührt.','Auf ein Signal zur nahen Markierung gehen und dort anhalten.','Durch ein stehendes Reaktionsspiel mit Zeigen auf die passende Farbe ersetzen.'
),('reaction-tag','en','Reaction tag practises awareness, first steps and direction changes inside a clearly bounded area.','Links a clear cue to controlled acceleration and braking; chasing pressure and physical contact are excluded.','Mark a small rectangle with flat cones and explain stop, out-of-bounds and clear run-out routes.','Space athletes well apart; begin walking and respond to the agreed colour or verbal cue.','No pushing, grabbing or blocking; stop play after any fall and clear the area.','Change direction with short steps and controlled braking; no blind backward running.','Complete 4 x 20 seconds walking to a simple cue, resting 40 seconds.','Complete 5 x 30 seconds at easy pace with 30–45 seconds rest.','Complete 6 x 30 seconds; change only one rule or cue at a time.','Reduce the playing area rather than forcing speed; the stop cue always applies.','In pairs, walk to the matching line on a cue instead of running.','Respond easily for 20 seconds and stop safely on the signal.','Use two familiar cues for 30 seconds with controlled direction changes.','Cooperative colour search: everyone moves to a colour; nobody is tagged or eliminated.','Walk to a nearby marker on a cue and stop there.','Replace with a standing reaction game pointing to the matching colour.'
)) AS v(seed_key,locale,summary,purpose,setup,start_position,safety_notes,quality_criteria,beginner_prescription,standard_prescription,advanced_prescription,work_rest_guidance,level_1,level_2,level_3,child_youth_variant,prerequisites,fallback_exercise);

UPDATE exercise_translations AS t SET summary = g.summary
FROM exercises AS e, warmup_seed_enrichment AS g
WHERE g.seed_key=e.seed_key AND g.locale=t.locale AND t.exercise_id=e.id;

UPDATE exercise_details AS d SET
  purpose=g.purpose, setup=g.setup, start_position=g.start_position,
  safety_notes=g.safety_notes, quality_criteria=g.quality_criteria,
  beginner_prescription=g.beginner_prescription,
  standard_prescription=g.standard_prescription,
  advanced_prescription=g.advanced_prescription,
  work_rest_guidance=g.work_rest_guidance,
  level_1=g.level_1, level_2=g.standard_prescription, level_3=g.level_3,
  child_youth_variant=g.child_youth_variant, prerequisites=g.prerequisites,
  fallback_exercise=g.fallback_exercise
FROM exercises AS e, warmup_seed_enrichment AS g
WHERE g.seed_key=e.seed_key AND g.locale=d.locale AND d.exercise_id=e.id;

DELETE FROM exercise_execution_steps WHERE exercise_id IN (SELECT id FROM exercises WHERE seed_key IN (SELECT seed_key FROM warmup_seed_enrichment));
INSERT INTO exercise_execution_steps
SELECT e.id,g.locale,s.step_order,s.instruction
FROM warmup_seed_enrichment AS g JOIN exercises AS e ON e.seed_key=g.seed_key
JOIN (VALUES
('easy-jog','de',1,'Gehe eine Runde zügig und prüfe, ob der Weg frei ist.'),('easy-jog','de',2,'Trabe locker an; halte Arme und Hände entspannt.'),('easy-jog','de',3,'Laufe gleichmäßig und gehe zum Ende ruhig aus.'),
('easy-jog','en',1,'Walk one brisk lap and check that the route is clear.'),('easy-jog','en',2,'Begin an easy jog with relaxed arms and hands.'),('easy-jog','en',3,'Keep an even pace, then walk to cool the effort.'),
('walk-jog','de',1,'Gehe bis zum Startsignal in aufrechter Haltung.'),('walk-jog','de',2,'Wechsle auf das Signal in einen lockeren Trab.'),('walk-jog','de',3,'Kehre beim nächsten Signal ins Gehen zurück und atme ruhig.'),
('walk-jog','en',1,'Walk upright until the start signal.'),('walk-jog','en',2,'Change to an easy jog when signalled.'),('walk-jog','en',3,'Return to walking at the next cue and let breathing settle.'),
