('butt-kicks','hamstrings','primary'),('butt-kicks','calves','secondary'),('side-shuffle','adductors','primary'),('side-shuffle','glutes','secondary'),
('carioca','hips','primary'),('carioca','adductors','secondary'),('arm-circles','shoulders','primary'),('arm-circles','upper-back','secondary'),
('inchworm','full-body','primary'),('inchworm','shoulders','secondary'),('jumping-jacks','full-body','primary'),('reaction-tag','full-body','primary')
) AS m(seed_key,body_region_id,emphasis) ON m.seed_key=e.seed_key;

