  ('supported-single-leg-hinge','de','Einbeiniger Hip Hinge'),('supported-single-leg-hinge','en','Supported single-leg deadlift'),
  ('band-anti-rotation-press','de','Pallof Press'),('band-anti-rotation-press','en','Pallof press')
